window.QSBI_LESSONS=window.QSBI_LESSONS||{};QSBI_LESSONS[7]=[{"id":"07_19","g":7,"l":19,"topic":"Основные этапы в выполнении проекта: практикум","module":"Event-менеджмент","format":"Проектная мастерская","skills":["Лидерство","Командная работа","Принятие решений"],"goal":"К концу урока ученик сможет отметить, какие этапы проекта его команды уже выполнены, и сформулировать один конкретный следующий шаг с ответственным и сроком.","criteria":["Я отмечаю статус каждого этапа нашего проекта честно и с доказательством.","Я предлагаю 3 действия, чтобы спасти отстающий проект.","Я называю следующий шаг: что, кто и к какому дню."],"result":"Чек-лист статуса проекта команды (выполнено / в работе / не начато) и план «спасения» кейсового проекта-катастрофы с 3 действиями.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Практика (practice)","real":"Применение знаний на реальной задаче","shown":"Применение знаний на реальной задаче","truth":true,"first":"П"},{"term":"Статус этапа","real":"Отметка, на какой стадии работа: выполнено, в работе, не начато","shown":"Человек, который видит весь проект и помогает команде дойти до результата","truth":false,"first":"С"},{"term":"Следующий шаг","real":"Одно конкретное действие с ответственным и сроком","shown":"Одно конкретное действие с ответственным и сроком","truth":true,"first":"С"},{"term":"Отставание по срокам","real":"Задача не сделана к назначенному дню","shown":"Отметка, на какой стадии работа: выполнено, в работе, не начато","truth":false,"first":"О"},{"term":"Превышение бюджета","real":"Потрачено больше условных тенге, чем планировали","shown":"Потрачено больше условных тенге, чем планировали","truth":true,"first":"П"},{"term":"Менеджер проекта","real":"Человек, который видит весь проект и помогает команде дойти до результата","shown":"Задача не сделана к назначенному дню","truth":false,"first":"М"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Практика (practice)","def":"Применение знаний на реальной задаче"},{"term":"Статус этапа","def":"Отметка, на какой стадии работа: выполнено, в работе, не начато"},{"term":"Следующий шаг","def":"Одно конкретное действие с ответственным и сроком"},{"term":"Отставание по срокам","def":"Задача не сделана к назначенному дню"},{"term":"Превышение бюджета","def":"Потрачено больше условных тенге, чем планировали"},{"term":"Менеджер проекта","def":"Человек, который видит весь проект и помогает команде дойти до результата"}],"english":"project — проект; event — мероприятие; practice — практика","concepts":{"head":"Понятия","items":["Проект (project) идёт по этапам, и менеджер регулярно проверяет статус: выполнено, в работе, не начато.","Следующий шаг — одно действие, у которого есть исполнитель и срок."]},"steps":{"head":"Как проверять проект, по шагам","items":["Выписываем все этапы","Ставим статус с доказательством (есть фото, список, договорённость)","Находим «красные зоны» — отставание, конфликт, перерасход","Для каждой красной зоны выбираем действие","Записываем следующий шаг"]},"scheme":"Светофор проекта — три колонки «Зелёный: выполнено», «Жёлтый: в работе», «Красный: не начато или отстаёт»; внизу строка «Следующий шаг: что — кто — когда».","examples":[{"lab":"Казахстанский","text":"Команда в Караганде готовит кинопросмотр для школы, бюджет 10 000 условных тенге, но уже потратила 8 000 на попкорн и не купила билеты-распечатки. Спасение: перераспределить остаток 2 000, распечатать билеты в школе бесплатно, попросить родительский комитет помочь со стульями."},{"lab":"Мировой","text":"Крупные компании проводят «разбор статуса» каждую неделю, чтобы заметить отставание до того, как оно станет катастрофой."}],"mistake":{"myth":"Команда отмечает этап «выполнено», хотя он сделан наполовину","fix":"Спросите «Что можно показать прямо сейчас?» и переведите этап в «в работе»."},"check":[{"q":"Почему нужен статус с доказательством?","a":"Чтобы не обманывать себя и команду"},{"q":"Что делать с красной зоной?","a":"Выбрать конкретное действие и ответственного"},{"q":"Чем следующий шаг отличается от желания?","a":"У него есть исполнитель и срок"}],"kz":{"text":"Air Astana. Казахстанская авиакомпания Air Astana каждый день выполняет рейсы по жёсткому расписанию: если один этап (уборка салона, заправка, посадка) задерживается, сдвигается весь рейс.","link":""},"world":{"text":"В мире известен проект международного аэропорта Берлин-Бранденбург: его открытие переносили несколько лет из-за ошибок в планировании и контроле, и аэропорт открылся только в 2020 году вместо 2011-го.","link":""},"fact":"Новый аэропорт Берлина (BER) планировали открыть в 2011 году, но из-за проблем с проектированием и контролем строительства его открыли только в октябре 2020 года — почти на 9 лет позже.","cards":[{"n":"1","title":"Проект-катастрофа","lines":["Ситуация: команда 7 класса готовит кинопросмотр для школы. До ивента 3 дня. Бюджет 10 000 условных тенге, потрачено уже 8 000 (попкорн 6 000, украшения 2 000). Не сделаны: билеты, афиша, договорённость о зале. Двое участников поссорились, кто ведёт ивент.","Задание: найдите 3 проблемы (сроки, бюджет, команда) и предложите по одному действию на каждую: что, кто, когда."],"hand":"Сдать: таблицу «Проблема — Действие — Кто — Когда».","answers":[]},{"n":"2","title":"Светофор нашего проекта","lines":["Задание: выпишите этапы вашего проекта: запуск, план, выполнение, встречи и отчёты, пересмотр и итог. Отметьте каждый: зелёный — выполнено (чем докажем?), жёлтый — в работе, красный — не начато или отстаёт."],"hand":"Сдать: светофор и строку «Следующий шаг: что — кто — к какому дню».","answers":[]},{"n":"3","title":"Открытка из будущего","lines":["Задание: «Через три месяца я рад, что сегодня мы … Моё действие на ближайшие 48 часов: …»"],"hand":"Сдать: вслух только действие.","answers":[]}],"practice":[{"type":"case","title":"Опера, которая опоздала на 10 лет","minutes":10,"source":"Сиднейский оперный театр, Австралия, 1957–1973","hook":"Театр планировали построить за 4 года. Сколько строили на самом деле?","story":["В 1957 году датский архитектор Йорн Утзон выиграл конкурс на проект оперного театра в Сиднее. Его крыши-«паруса» были очень смелыми.","Строить начали раньше, чем инженеры поняли, как сделать такие крыши. План был — закончить к 1963 году.","Проект много раз переделывали, бюджет рос, архитектор ушёл с проекта в 1966 году."],"question":"Когда, по-вашему, открыли театр?","options":["В 1973 году — на 10 лет позже плана","В 1960 году — раньше срока","В 1963 году — точно в срок","Его так и не достроили"],"answerIndex":0,"reveal":"Театр открыли в 1973 году, а стоил он в десятки раз дороже первой сметы. Главная ошибка — начали стройку, не пройдя этап планирования до конца. Сегодня это символ Австралии и урок для менеджеров проектов.","teams":"Команды: расставьте этапы проекта ярмарки по порядку: идея, план, ресурсы, выполнение, контроль, итоги. Что будет, если пропустить план?","takeaway":"Пропущенный этап планирования потом стоит в разы дороже."},{"type":"case","title":"Братья Райт и 1000 планеров","minutes":8,"source":"Уилбур и Орвилл Райт, Китти-Хок, США, 1900–1903","hook":"Два владельца велосипедной мастерской построили первый самолёт. Как?","story":["Братья Райт не были учёными — у них была мастерская велосипедов.","С 1900 по 1902 год они строили планеры, испытывали их на дюнах Китти-Хок, записывали результаты и даже построили свою аэродинамическую трубу.","17 декабря 1903 года их самолёт с мотором впервые пролетел 12 секунд."],"question":"Что, по-вашему, было главным в их подходе к проекту?","options":["Им повезло с ветром","Маленькие испытания, записи результатов и улучшения шаг за шагом","Они купили чертежи","Сразу построили большой самолёт"],"answerIndex":1,"reveal":"Райты прошли много циклов «сделали — проверили — записали — улучшили». Каждый этап проекта давал данные для следующего. Так маленькая мастерская обогнала богатые команды.","teams":"Команды: придумайте «маленькое испытание» для своего проекта, которое можно провести за один день.","takeaway":"Проект продвигается циклами: сделал, проверил, улучшил."}],"homework":"Выполнить свой следующий шаг из чек-листа и принести доказательство (фото, список, сообщение-договорённость).","support":"Готовый список из 6 возможных «спасательных» действий для кейса: ученик выбирает 3 и объясняет выбор; шаблон фразы «Следующий шаг: я … до …».","advanced":"Посчитать, как перераспределить бюджет кейсового проекта, чтобы закрыть перерасход, и предложить, как предупредить такую ситуацию в следующий раз.","photo":{"src":"lessons/img/07_19.jpg","author":"Walls.io","q":["Что вы видите на фото? Как это связано с нашей темой?","На каком этапе менеджеры могли заметить проблему раньше и что бы вы сделали?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l19.pptx","name":"19. Основные этапы в выполнении проекта — практикум (7 кл).pptx","mb":1.4}},{"id":"07_20","g":7,"l":20,"topic":"Причины конфликтов, их влияние на проект","module":"Event-менеджмент","format":"Проектная мастерская","skills":["Командная работа","Переговоры","Критическое мышление"],"goal":"К концу урока ученик сможет определить тип конфликта в команде проекта (задач, ценностей или отношений), назвать его причину и предложить способ решения.","criteria":["Я определяю тип конфликта: задач, ценностей или отношений.","Я называю причину конфликта и объясняю, как он влияет на сроки или качество проекта.","Я предлагаю решение, которое честно для обеих сторон."],"result":"Карта разбора конфликта: тип, причина, влияние на проект и 2 варианта решения для кейса команды.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Конфликт (conflict)","real":"Столкновение мнений или интересов людей, которые работают вместе","shown":"Столкновение мнений или интересов людей, которые работают вместе","truth":true,"first":"К"},{"term":"Конфликт задач","real":"Спор о том, что и как делать: какой план выбрать, кто делает какую часть","shown":"Решение, где каждая сторона уступает часть, чтобы двигаться дальше","truth":false,"first":"К"},{"term":"Конфликт ценностей","real":"Спор о том, что важно: честность, качество, скорость, традиции","shown":"Спор о том, что важно: честность, качество, скорость, традиции","truth":true,"first":"К"},{"term":"Конфликт отношений","real":"Неприязнь или обида между людьми, не связанная напрямую с задачей","shown":"Спор о том, что и как делать: какой план выбрать, кто делает какую часть","truth":false,"first":"К"},{"term":"Причина конфликта","real":"То, из-за чего начался спор: нехватка информации, нечёткие роли, разные цели","shown":"То, из-за чего начался спор: нехватка информации, нечёткие роли, разные цели","truth":true,"first":"П"},{"term":"Компромисс","real":"Решение, где каждая сторона уступает часть, чтобы двигаться дальше","shown":"Неприязнь или обида между людьми, не связанная напрямую с задачей","truth":false,"first":"К"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Конфликт (conflict)","def":"Столкновение мнений или интересов людей, которые работают вместе"},{"term":"Конфликт задач","def":"Спор о том, что и как делать: какой план выбрать, кто делает какую часть"},{"term":"Конфликт ценностей","def":"Спор о том, что важно: честность, качество, скорость, традиции"},{"term":"Конфликт отношений","def":"Неприязнь или обида между людьми, не связанная напрямую с задачей"},{"term":"Причина конфликта","def":"То, из-за чего начался спор: нехватка информации, нечёткие роли, разные цели"},{"term":"Компромисс","def":"Решение, где каждая сторона уступает часть, чтобы двигаться дальше"}],"english":"project — проект; conflict — конфликт; event — мероприятие","concepts":{"head":"Понятия","items":["Конфликт (conflict) — это столкновение мнений в команде проекта (project).","Он бывает трёх типов: конфликт задач (спорим, как делать), конфликт ценностей (спорим, что важно), конфликт отношений (обиды между людьми)."]},"steps":{"head":"Как разбирать конфликт, по шагам","items":["Остановиться и описать факты без обвинений","Определить тип","Найти причину — чаще всего это нечёткие роли, нехватка информации или разные цели","Оценить влияние на проект: сроки, бюджет, атмосферу","Предложить решение: договорённость, компромисс, помощь менеджера"]},"scheme":"Три круга «Задачи», «Ценности», «Отношения»; от каждого стрелка к квадрату «Влияние на проект: сроки, бюджет, качество» и далее к квадрату «Решение».","examples":[{"lab":"Казахстанский","text":"Команда в Актобе готовит ивент (event) «Наурыз-квест», бюджет 15 000 условных тенге. Двое спорят: один хочет потратить 10 000 на призы, другой — на костюмы. Это конфликт задач; решение — разделить бюджет 7 000 и 5 000, а 3 000 оставить в резерве."},{"lab":"Мировой","text":"В спортивных командах тренеры проводят разбор после проигрыша не для поиска виноватого, а чтобы договориться о плане на следующую игру."}],"mistake":{"myth":"Ученики сразу ищут, кто виноват","fix":"Перепишите фразу «Он всё испортил» на фразу о факте «Афиша не готова к среде» и только потом обсуждайте решение."},"check":[{"q":"Всегда ли конфликт плохо?","a":"Нет, конфликт задач может привести к лучшему плану"},{"q":"Какой конфликт опаснее для проекта?","a":"Конфликт отношений, если его не решать: люди перестают работать вместе"},{"q":"С чего начинается разбор?","a":"С фактов без обвинений"}],"kz":{"text":"Байконур и международное сотрудничество. С казахстанского космодрома Байконур стартуют экипажи на Международную космическую станцию, где вместе работают люди разных стран и культур. Используйте как вводный пример перед разбором кейсов.","link":"в таком проекте конфликт может сорвать миссию, поэтому важны чёткие роли и правила общения."},"world":{"text":"ЦУР ООН № 16 «Мир, правосудие и эффективные институты» говорит о мирном решении споров. Даже в больших международных проектах, например на Международной космической станции, где работают космонавты разных стран, заранее договариваются о правилах общения, чтобы споры не мешали работе.","link":""},"fact":"Слово «компромисс» происходит от латинского compromissum — взаимное обещание сторон подчиниться решению третьего лица. Так в Древнем Риме решали споры: стороны заранее обещали принять решение посредника.","cards":[{"n":"2","title":"Кейсы конфликтов (каждой команде один)","lines":["Кейс А. Команда готовит «Наурыз-квест», бюджет 15 000 условных тенге. Айгерим хочет 10 000 потратить на призы, Данияр — на костюмы. До ивента 5 дней.","Кейс Б. Арман сделал афишу за ночь, но с ошибками. Алия считает, что лучше переделать и опоздать на день, Арман — что главное успеть.","Кейс В. Дана перестала отвечать в чате команды после того, как её идею высмеяли. Её часть работы — регистрация гостей.","Задание: запишите факты без обвинений, тип конфликта, причину, влияние на проект, 2 решения и выберите лучшее."],"hand":"Сдать: карту разбора на А4.","answers":[]},{"n":"3","title":"Открытка из будущего","lines":["Задание: «Через три месяца в нашей команде нет обид, потому что я … Действие на 48 часов: …»"],"hand":"Сдать: вслух только действие.","answers":[]}],"practice":[{"type":"case","title":"Братья, которые поссорились навсегда","minutes":10,"source":"Адольф и Рудольф Дасслер, Херцогенаурах, Германия, 1948","hook":"Два брата делали обувь вместе. После ссоры появилось две мировые компании.","story":["В 1920-х братья Адольф (Ади) и Рудольф Дасслер открыли обувную фабрику в немецком городке Херцогенаурах.","Их кроссовки носили олимпийские чемпионы. Но братья постоянно ссорились — по работе и по семейным делам.","В 1948 году они разделили компанию."],"question":"Какие компании появились после ссоры?","options":["Adidas и Puma","Asics и Mizuno","Fila и Kappa","Nike и Reebok"],"answerIndex":0,"reveal":"Ади назвал свою компанию Adidas, а Рудольф — Puma. Фабрики стояли на разных берегах одной речки, а город десятилетиями был разделён на «два лагеря». Конфликт, который не решили разговором, длился всю жизнь.","teams":"Команды: в вашем проекте двое спорят, кто главный. Предложите 3 способа решить конфликт, пока он не разрушил команду.","takeaway":"Нерешённый конфликт может разделить даже самую сильную команду."},{"type":"case","title":"Кто будет презентовать?","minutes":8,"source":"Условная ситуация","hook":"До защиты 2 дня. Двое хотят выступать, а третий ничего не делает.","story":["Команда из 4 человек готовит проект «Школьное кафе».","Айгерим и Данияр оба хотят выступать на защите и спорят уже второй день.","Ерлан обиделся, что его идею не взяли, и перестал помогать. Четвёртый участник молчит."],"question":"Что лучше всего сделать команде прямо сейчас?","options":["Ждать, пока само пройдёт","Собраться, выслушать каждого и распределить роли по сильным сторонам","Пусть учитель решит","Выгнать Ерлана"],"answerIndex":1,"reveal":"Конфликт мешает проекту: время уходит на споры. Можно разделить выступление на двоих, а Ерлану дать роль, где пригодится его идея. Главное — говорить об интересах, а не о том, кто прав.","teams":"Команды: разыграйте этот разговор за 3 минуты. Найдите решение, при котором выигрывают все четверо.","takeaway":"Конфликт решают через интересы, а не через «кто прав»."}],"homework":"Записать 3 правила общения для своей проектной команды, которые помогут избегать конфликтов отношений, и обсудить их с командой.","support":"Таблица-подсказка с примерами фраз для каждого типа конфликта и шаблон «я-сообщения»: «Я волнуюсь, когда…, потому что…, давай…».","advanced":"Придумать свой кейс конфликта ценностей для ивента и решение, которое не является простым компромиссом, а даёт выгоду обеим сторонам.","photo":{"src":"lessons/img/07_20.jpg","author":"Afif Ramdhasuma","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие правила общения нужны нашей команде, чтобы конфликт задач не превратился в конфликт отношений?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l20.pptx","name":"20. Причины конфликтов, их влияние на проект (7 кл).pptx","mb":1.5}},{"id":"07_21","g":7,"l":21,"topic":"Управление временем при подготовке к проекту","module":"Event-менеджмент","format":"Проектная мастерская","skills":["Командная работа","Принятие решений","Лидерство"],"goal":"К концу урока ученик сможет составить график подготовки ивента из 6–8 задач с дедлайнами и ответственными и выделить задачи, которые нельзя сдвигать.","criteria":["Я разбиваю подготовку ивента на 6–8 конкретных задач.","Я ставлю каждой задаче реальный дедлайн и ответственного.","Я объясняю, какие задачи важнее и что сделать, если сроки горят."],"result":"Командный график подготовки ивента (чек-лист с дедлайнами по дням) и мини-план «что делаем, если не успеваем».","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Управление временем (time management)","real":"Умение планировать задачи так, чтобы успевать к сроку","shown":"Умение планировать задачи так, чтобы успевать к сроку","truth":true,"first":"У"},{"term":"Дедлайн","real":"Последний срок, к которому задача должна быть готова","shown":"Список задач, где отмечают выполненное","truth":false,"first":"Д"},{"term":"Цель","real":"Конкретный результат, к которому идёт команда, например провести ивент (event) 20 декабря","shown":"Конкретный результат, к которому идёт команда, например провести ивент (event) 20 декабря","truth":true,"first":"Ц"},{"term":"Дисциплина","real":"Привычка выполнять договорённости вовремя, даже когда не хочется","shown":"Последний срок, к которому задача должна быть готова","truth":false,"first":"Д"},{"term":"Саморазвитие","real":"Постоянное улучшение своих навыков, в том числе умения планировать","shown":"Постоянное улучшение своих навыков, в том числе умения планировать","truth":true,"first":"С"},{"term":"Чек-лист","real":"Список задач, где отмечают выполненное","shown":"Привычка выполнять договорённости вовремя, даже когда не хочется","truth":false,"first":"Ч"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Управление временем (time management)","def":"Умение планировать задачи так, чтобы успевать к сроку"},{"term":"Дедлайн","def":"Последний срок, к которому задача должна быть готова"},{"term":"Цель","def":"Конкретный результат, к которому идёт команда, например провести ивент (event) 20 декабря"},{"term":"Дисциплина","def":"Привычка выполнять договорённости вовремя, даже когда не хочется"},{"term":"Саморазвитие","def":"Постоянное улучшение своих навыков, в том числе умения планировать"},{"term":"Чек-лист","def":"Список задач, где отмечают выполненное"}],"english":"project — проект; time management — управление временем; event — мероприятие","concepts":{"head":"Понятия","items":["Управление временем (time management) в проекте (project) — это план, где у каждой задачи есть дедлайн и ответственный.","Цель задаёт финиш, дедлайны — промежуточные точки, дисциплина помогает в них попадать."]},"steps":{"head":"Как составить график, по шагам","items":["Записываем дату ивента","Выписываем все задачи (тема, бюджет, место, афиша, реквизит, регистрация гостей, репетиция)","Идём от даты ивента назад и ставим дедлайны","Отмечаем задачи, от которых зависят другие (без места нельзя печатать афишу)","Добавляем 1–2 дня запаса","Назначаем ответственных"]},"scheme":"Горизонтальная линия-календарь от сегодня до дня ивента; на ней флажки-дедлайны, под ними имена ответственных; красным обведены задачи, которые нельзя сдвигать.","examples":[{"lab":"Казахстанский","text":"Команда в Павлодаре проводит турнир по настольным играм 20 декабря, бюджет 8 000 условных тенге. Дедлайны: 10 декабря — согласовать зал, 13 — купить призы на 5 000, 15 — повесить афишу, 18 — репетиция, 19 — запасной день."},{"lab":"Мировой","text":"При подготовке крупных концертов график монтажа сцены расписан по часам, потому что задержка одной бригады сдвигает всех."}],"mistake":{"myth":"Все дедлайны ставят на последний день перед ивентом","fix":"Попросите показать, что произойдёт, если в этот день заболеет один человек, и перенесите задачи раньше. Что делать, если всё идёт не так: глубокий вдох, список «что горит», одна задача за раз, просить помощи у команды."},"check":[{"q":"Почему планируем от даты ивента назад?","a":"Так видно, сколько времени реально осталось"},{"q":"Зачем запасной день?","a":"На случай непредвиденных обстоятельств"},{"q":"Какую задачу делать первой?","a":"Ту, от которой зависят другие"}],"kz":{"text":"Зимние Азиатские игры 2011 в Астане и Алматы. Казахстан принимал VII зимние Азиатские игры в 2011 году, и к ним готовили спортивные объекты и программу соревнований по графику.","link":"большой ивент невозможен без дедлайнов и ответственных."},"world":{"text":"Олимпийские игры проводят по строгому графику: город-организатор получает право на игры примерно за 7 лет и сдаёт объекты по контрольным срокам. Если стадион не готов к дедлайну, страдает вся программа.","link":""},"fact":"Метод «Помидора» придумал итальянский студент Франческо Чирилло в конце 1980-х годов: он работал 25 минут по кухонному таймеру в форме помидора, а потом отдыхал 5 минут. Сейчас этот метод используют по всему миру для управления временем.","cards":[{"n":"2","title":"График подготовки ивента","lines":["Ситуация: турнир по настольным играм для 6 классов 20 декабря в 14:00. Сегодня 6 декабря. Бюджет 8 000 условных тенге: призы 5 000, распечатки 1 000, угощение 2 000. Задачи: согласовать зал, выбрать игры, купить призы, сделать афишу, повесить афишу, собрать заявки, подготовить таблицу результатов, репетиция.","Задание: расставьте задачи по датам от 6 до 19 декабря, назначьте ответственных, отметьте 2 задачи, которые нельзя сдвигать, и оставьте 1 запасной день. Напишите 3 действия на случай «не успеваем»."],"hand":"Сдать: график на А3.","answers":[]},{"n":"3","title":"Открытка из будущего","lines":["Задание: «Прошло три месяца. Я научился успевать к дедлайнам, потому что … Действие на 48 часов: …»"],"hand":"Сдать: вслух только действие.","answers":[]}],"practice":[{"type":"case","title":"Закон Паркинсона","minutes":9,"source":"Сирил Норткот Паркинсон, статья в журнале The Economist, 1955","hook":"Почему на работу всегда не хватает времени, сколько бы его ни дали?","story":["В 1955 году британский историк Сирил Паркинсон написал шуточную статью о чиновниках.","Он заметил: пожилая дама может весь день отправлять одну открытку — выбирать её, искать очки, адрес, идти на почту.","Из этого он вывел закон."],"question":"Как звучит закон Паркинсона?","options":["Лучше сделать позже, чем никогда","Время — деньги","Работа заполняет всё время, отведённое на неё","Чем больше работаешь, тем больше отдыхаешь"],"answerIndex":2,"reveal":"«Работа заполняет всё время, отведённое на неё». Если на проект дали месяц — он займёт месяц, а если неделю, часто успевают за неделю. Поэтому полезно ставить себе короткие промежуточные сроки.","teams":"Команды: разбейте подготовку к проекту на 5 задач и дайте каждой свой короткий срок (дедлайн).","takeaway":"Короткие промежуточные сроки защищают от закона Паркинсона."},{"type":"case","title":"Матрица Эйзенхауэра","minutes":8,"source":"Метод, названный в честь Дуайта Эйзенхауэра, президента США в 1953–1961 годах","hook":"Президент страны и генерал — как он успевал всё?","story":["Дуайту Эйзенхауэру приписывают мысль: «Важное редко бывает срочным, а срочное редко бывает важным».","По этой идее появилась матрица: все дела делят на 4 группы по двум вопросам — важно ли? срочно ли?","Важное и срочное — делать сразу. Важное, но не срочное — запланировать. Срочное, но не важное — поручить. Не важное и не срочное — убрать."],"question":"Куда в матрице попадёт «подготовка к защите проекта через 2 недели»?","options":["Не важно — удалить","Срочно и важно — бросить всё","Срочно, но не важно — поручить","Важно, но не срочно — запланировать"],"answerIndex":3,"reveal":"Подготовка к защите важна, но пока не срочна — её нужно запланировать заранее. Если откладывать, через 2 недели она станет «срочно и важно», и придётся работать в панике.","teams":"Команды: разложите 8 дел школьника по 4 квадратам матрицы.","takeaway":"Важные дела планируют заранее, пока они не стали срочными."}],"homework":"Составить личный график на неделю: 5 дел с дедлайнами, отметить, что выполнено, и принести на урок.","support":"Готовый список из 8 задач ивента в перепутанном порядке: ученик выстраивает их по порядку и ставит даты; подсказка «сначала то, от чего зависят другие».","advanced":"Рассчитать, сколько дней запаса осталось у команды, и предложить, какие 2 задачи можно делать параллельно, чтобы ускорить подготовку.","photo":{"src":"lessons/img/07_21.jpg","author":"CHUTTERSNAP","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему у Олимпиады есть промежуточные дедлайны, а не только дата открытия?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l21.pptx","name":"21. Управление временем при подготовке к проекту (7 кл).pptx","mb":1.4}},{"id":"07_22","g":7,"l":22,"topic":"Анализ проекта, новый ивент","module":"Event-менеджмент","format":"Проектная мастерская","skills":["Критическое мышление","Командная работа","Креативность"],"goal":"К концу урока ученик сможет назвать 5 вопросов для анализа проведённого ивента (что сработало, что улучшить, что узнали) и применить их к одному проекту.","criteria":["Я называю вопросы для анализа проекта: что сработало, что не сработало, что улучшить.","Я отвечаю на них с фактами (цифры, отзывы, наблюдения).","Я предлагаю идею нового ивента, где учтено одно улучшение."],"result":"Лист анализа проекта: 5 вопросов анализа с ответами команды по проведённому ивенту и идея нового ивента с учётом выводов.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Ивент (event)","real":"Мероприятие, которое готовят для определённых гостей с конкретной целью","shown":"Мероприятие, которое готовят для определённых гостей с конкретной целью","truth":true,"first":"И"},{"term":"Анализ проекта","real":"Разбор после ивента: что получилось, что нет и почему","shown":"Цифры и факты: сколько пришло гостей, сколько потратили, что услышали","truth":false,"first":"А"},{"term":"Обратная связь","real":"Мнения гостей и участников о проекте","shown":"Мнения гостей и участников о проекте","truth":true,"first":"О"},{"term":"Ретроспектива","real":"Встреча команды после проекта для анализа","shown":"Разбор после ивента: что получилось, что нет и почему","truth":false,"first":"Р"},{"term":"Улучшение","real":"Конкретное изменение, которое сделаем в следующем проекте","shown":"Конкретное изменение, которое сделаем в следующем проекте","truth":true,"first":"У"},{"term":"Итоги","real":"Цифры и факты: сколько пришло гостей, сколько потратили, что услышали","shown":"Встреча команды после проекта для анализа","truth":false,"first":"И"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ивент (event)","def":"Мероприятие, которое готовят для определённых гостей с конкретной целью"},{"term":"Анализ проекта","def":"Разбор после ивента: что получилось, что нет и почему"},{"term":"Обратная связь","def":"Мнения гостей и участников о проекте"},{"term":"Ретроспектива","def":"Встреча команды после проекта для анализа"},{"term":"Улучшение","def":"Конкретное изменение, которое сделаем в следующем проекте"},{"term":"Итоги","def":"Цифры и факты: сколько пришло гостей, сколько потратили, что услышали"}],"english":"project — проект; event — мероприятие","concepts":{"head":"Понятия","items":["После ивента (event) проект (project) не заканчивается: команда проводит анализ проекта, или ретроспективу.","Она нужна, чтобы следующий ивент был лучше."]},"steps":{"head":"Как анализировать, по шагам","items":["Собрать итоги — цифры и отзывы","Ответить на 5 вопросов: Достигли ли цели? Что сработало хорошо? Что не сработало? Почему? Что сделаем иначе?","Выбрать 1–3 улучшения","Поблагодарить команду и гостей","Записать выводы, чтобы использовать их в новом ивенте"]},"scheme":"«звезда анализа» из 5 лучей — Цель? Сработало? Не сработало? Почему? Что изменим? В центре — «Новый ивент».","examples":[{"lab":"Казахстанский","text":"Класс в Кокшетау провёл новогоднюю ярмарку. Цель — 60 гостей, пришло 45; планировали потратить 12 000 условных тенге, потратили 13 500. Сработало: выпечка раскупили за час. Не сработало: афишу повесили поздно. Улучшение: вешать афишу за неделю."},{"lab":"Мировой","text":"После каждого чемпионата мира по футболу организаторы публикуют отчёт с выводами для следующей страны-хозяйки."}],"mistake":{"myth":"Анализ превращается в поиск виноватых или в «всё было отлично»","fix":"Правило «сначала факт, потом вывод, потом действие» и запрет на имена в разделе «не сработало»."},"check":[{"q":"Зачем анализ, если ивент уже прошёл?","a":"Чтобы не повторять ошибки и сохранить удачные решения"},{"q":"Чем «было скучно» отличается от факта?","a":"Факт: «20 из 45 гостей ушли через 15 минут»"},{"q":"Что делать с выводами?","a":"Превратить в улучшения нового ивента"}],"kz":{"text":"Алматы Марафон. Ежегодный городской забег в Алматы проводится много лет, и организаторы каждый год меняют что-то по итогам предыдущего: маршрут, пункты питания, регистрацию.","link":"регулярный ивент становится лучше благодаря анализу."},"world":{"text":"Международный олимпийский комитет после каждых Олимпийских игр собирает отчёты и передаёт опыт следующему городу-организатору, чтобы он не повторял ошибок.","link":""},"fact":"В компании Toyota с середины XX века используют метод «5 почему»: чтобы найти настоящую причину проблемы, задают вопрос «почему?» несколько раз подряд. Метод связывают с инженером Тайити Оно, создателем производственной системы Toyota.","cards":[{"n":"2","title":"Итоги новогодней ярмарки","lines":["Данные: цель — 60 гостей, пришло 45. План расходов — 12 000 условных тенге, факт — 13 500 (перерасход на украшения). Выручка — 18 000 условных тенге. Выпечку раскупили за 1 час, напитки остались. Афишу повесили за 2 дня до ивента. Отзывы: «весело», «долго ждали на кассе», «мало сладкого».","Задание: ответьте на 5 вопросов звезды анализа, опираясь на данные, выберите 2 улучшения и предложите новый ивент, где они учтены."],"hand":"Сдать: лист анализа на А3.","answers":[]},{"n":"3","title":"Открытка из будущего","lines":["Задание: «Через три месяца наш новый ивент прошёл лучше, потому что мы … Моё действие на 48 часов: …»"],"hand":"Сдать: вслух только действие.","answers":[]}],"practice":[{"type":"case","title":"Фестиваль, которого не было","minutes":10,"source":"Fyre Festival, Багамы, апрель 2017","hook":"Обещали роскошный фестиваль на острове. Что получили гости?","story":["Организаторы рекламировали музыкальный фестиваль на Багамах через известных блогеров и моделей: виллы, лучшая еда, звёзды на сцене.","Билеты стоили тысячи долларов. Но к началу фестиваля почти ничего не было готово.","Гости приехали — и увидели палатки для беженцев после урагана и бутерброды с сыром в пенопластовых коробках."],"question":"Какая главная ошибка организаторов?","options":["Слишком дешёвые билеты","Реклама обогнала подготовку: обещали то, что не успевали сделать","Мало блогеров","Плохая погода"],"answerIndex":1,"reveal":"Фестиваль отменили в первый же день, гостей с трудом вывезли с острова, а организатор попал в тюрьму за мошенничество. Урок для анализа проекта: обещать можно только то, что реально успеешь сделать.","teams":"Команды: проанализируйте прошлый ивент класса по 3 вопросам: что обещали? что сделали? где разница?","takeaway":"Нельзя обещать больше, чем успеваешь сделать."},{"type":"case","title":"Разбор после действия","minutes":8,"source":"After Action Review — метод армии США, используется во многих компаниях","hook":"Как команды учатся на каждом проекте, а не повторяют ошибки?","story":["После каждого учения в армии США проводят короткий разбор — After Action Review.","Отвечают на 4 вопроса: что планировали? что произошло на самом деле? почему так? что сделаем по-другому?","Правило: разбирают действия, а не ищут виноватых."],"question":"Почему, по-вашему, на разборе запрещено искать виноватых?","options":["Виноватых не бывает","Так требует начальство","Чтобы было быстрее","Иначе люди скрывают ошибки, и команда ничему не учится"],"answerIndex":3,"reveal":"Если за ошибку ругают — её скрывают, и команда повторяет её снова. Если её спокойно разбирают — команда растёт. Этот метод используют компании, больницы и спортивные клубы.","teams":"Команды: проведите 4-вопросный разбор последнего проекта класса и предложите идею нового ивента.","takeaway":"Разбор проекта ищет уроки, а не виноватых."}],"homework":"Составить короткую анкету из 3 вопросов для гостей ивента (что понравилось, что улучшить, придёте ли снова) и опросить 3 человек.","support":"Шаблон с 5 вопросами и началами фраз: «Сработало…, потому что…», «Не сработало…, потому что…», «В следующий раз мы…».","advanced":"Посчитать, на сколько процентов команда не достигла цели по гостям и бюджету, и предложить улучшение, которое закроет эту разницу.","photo":{"src":"lessons/img/07_22.jpg","author":"Fujiphilm","q":["Что вы видите на фото? Как это связано с нашей темой?","Какой опыт нашего ивента мы передали бы следующему 7 классу?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l22.pptx","name":"22. Анализ проекта, новый ивент (7 кл).pptx","mb":1.6}},{"id":"07_23","g":7,"l":23,"topic":"Анализ проекта, новый ивент: практикум","module":"Event-менеджмент","format":"Проектная мастерская","skills":["Командная работа","Критическое мышление","Принятие решений"],"goal":"К концу урока команда сможет проанализировать проведённый ивент по фактам и предложить 3 конкретных улучшения для своего следующего школьного ивента.","criteria":["Я опираюсь на факты прошлого ивента: цифры, отзывы, наблюдения.","Я формулирую 3 улучшения так, что понятно, кто и что сделает.","Я показываю, где эти улучшения появятся в плане нового ивента."],"result":"Командный паспорт нового ивента: выводы по прошлому ивенту и 3 улучшения, встроенные в план нового (кинопросмотр, квест, открытый урок или турнир).","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Практика (practice)","real":"Применение знаний на своём проекте (project)","shown":"Применение знаний на своём проекте (project)","truth":true,"first":"П"},{"term":"Ивент (event)","real":"Мероприятие с целью, гостями и программой","shown":"Человек, который отвечает за выполнение задачи","truth":false,"first":"И"},{"term":"Паспорт ивента","real":"Краткое описание: цель, гости, дата, место, бюджет, роли","shown":"Краткое описание: цель, гости, дата, место, бюджет, роли","truth":true,"first":"П"},{"term":"Улучшение","real":"Конкретное изменение по итогам анализа","shown":"Мероприятие с целью, гостями и программой","truth":false,"first":"У"},{"term":"Целевая аудитория","real":"Гости, для которых делаем ивент","shown":"Гости, для которых делаем ивент","truth":true,"first":"Ц"},{"term":"Ответственный","real":"Человек, который отвечает за выполнение задачи","shown":"Конкретное изменение по итогам анализа","truth":false,"first":"О"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Практика (practice)","def":"Применение знаний на своём проекте (project)"},{"term":"Ивент (event)","def":"Мероприятие с целью, гостями и программой"},{"term":"Паспорт ивента","def":"Краткое описание: цель, гости, дата, место, бюджет, роли"},{"term":"Улучшение","def":"Конкретное изменение по итогам анализа"},{"term":"Целевая аудитория","def":"Гости, для которых делаем ивент"},{"term":"Ответственный","def":"Человек, который отвечает за выполнение задачи"}],"english":"project — проект; event — мероприятие; practice — практика","concepts":{"head":"Понятия","items":["Анализ проекта превращается в пользу, только когда выводы становятся улучшениями нового ивента (event).","Улучшение должно быть конкретным: что изменим, кто сделает, как проверим."]},"steps":{"head":"Как работаем, по шагам","items":["Вспоминаем факты прошлого ивента","Выбираем 3 главные проблемы или точки роста","Переводим каждую в улучшение по формуле «Было — Станет — Кто отвечает»","Выбираем новый ивент для школы и заполняем его паспорт","Встраиваем 3 улучшения в паспорт"]},"scheme":"Таблица «Было — Станет — Кто отвечает — Где в плане», рядом паспорт ивента из 6 строк: цель, гости, дата и место, программа, бюджет, роли.","examples":[{"lab":"Казахстанский","text":"Команда в Таразе проводила квест, пришло 30 из 40 приглашённых, а очередь на старте заняла 15 минут. Улучшения: регистрация заранее через онлайн-форму; старт командами по расписанию каждые 3 минуты; напоминание в чате класса за день. Бюджет нового ивента — 9 000 условных тенге, из них 1 000 в резерве."},{"lab":"Мировой","text":"Кинофестивали каждый год меняют систему продажи билетов по отзывам зрителей, чтобы уменьшить очереди."}],"mistake":{"myth":"Улучшения звучат как пожелания («сделать лучше», «быть организованнее»)","fix":"Задайте вопрос «Что именно человек сделает в понедельник?» и перепишите."},"check":[{"q":"Почему улучшений 3, а не 10?","a":"Три команда реально успеет сделать"},{"q":"Как понять, что улучшение конкретное?","a":"В нём есть действие, ответственный и проверка"},{"q":"Откуда брать идеи улучшений?","a":"Из фактов и отзывов гостей"}],"kz":{"text":"Фестиваль «Шабыт» в Астане. Международный фестиваль творческой молодёжи «Шабыт» проводится в Астане много лет и каждый год обновляет программу и форматы.","link":"регулярный ивент развивается за счёт анализа и улучшений."},"world":{"text":"ЦУР ООН № 4 «Качественное образование» говорит о доступном и интересном обучении для всех. Школьный ивент — открытый урок или кинопросмотр с обсуждением — может работать на эту цель.","link":""},"fact":"Первый публичный платный киносеанс провели братья Люмьер 28 декабря 1895 года в Париже, в «Гран-кафе» на бульваре Капуцинок: зрители смотрели десять коротких фильмов. Это считают днём рождения кино как ивента.","cards":[{"n":"2","title":"Паспорт нового ивента","lines":["Данные прошлого квеста: пришло 30 из 40 приглашённых; очередь на старте 15 минут; потратили 9 500 условных тенге при плане 9 000; отзывы: «интересные загадки», «долго ждали», «не знали, где финиш».","Задание: 1) Заполните таблицу «Было — Станет — Кто отвечает — Где в плане» для 3 улучшений. 2) Выберите новый ивент (кинопросмотр, квест, открытый урок, турнир) и заполните паспорт: цель, гости, дата и место, программа, бюджет 9 000 условных тенге с резервом, роли."],"hand":"Сдать: таблицу и паспорт на А3.","answers":[]},{"n":"3","title":"Открытка из будущего","lines":["Задание: «Через три месяца наш ивент стал лучше, потому что мы … Моё действие на 48 часов: …»"],"hand":"Сдать: вслух только действие.","answers":[]}],"practice":[{"type":"case","title":"Ждали 50 тысяч, пришли 400","minutes":9,"source":"Музыкальный фестиваль Вудсток, США, август 1969","hook":"Организаторы продали билеты. Но людей пришло в несколько раз больше.","story":["Организаторы фестиваля Вудсток ожидали около 50 тысяч зрителей.","Но на ферму в штате Нью-Йорк приехало около 400 тысяч человек. Дороги встали в пробках на много километров.","Заборы и кассы не были достроены, еды и туалетов не хватало."],"question":"Что, по-вашему, пришлось сделать организаторам?","options":["Выгнать всех без билетов","Отменить фестиваль","Поднять цену билетов","Объявить фестиваль бесплатным — проверять билеты было невозможно"],"answerIndex":3,"reveal":"Организаторы объявили вход бесплатным, и фестиваль стал легендой, но сами они понесли большие убытки. Урок: проект должен учитывать «а что, если людей придёт больше или меньше?».","teams":"Команды: для нового ивента класса посчитайте, что будет, если гостей придёт вдвое больше или вдвое меньше.","takeaway":"Анализ проекта учитывает разные сценарии посещаемости."},{"type":"case","title":"Квест для начальной школы","minutes":8,"source":"Условная ситуация","hook":"Класс проводит квест для младших. Как понять, получилось ли?","story":["7 класс устроил квест для 3 классов: 5 станций, 40 минут, приз — грамоты.","Одна станция задерживала всех: там было слишком сложное задание, образовалась очередь.","После квеста дети сказали, что было весело, но двое плакали, потому что «не успели»."],"question":"Что важнее всего изменить в следующем квесте?","options":["Проверить задания на младших заранее и выровнять время на станциях","Сделать квест для старших","Ничего, всем понравилось","Убрать призы"],"answerIndex":0,"reveal":"Отзывы и наблюдения показали «узкое место» — одну станцию. Если заранее прогнать квест с 2–3 детьми, такую проблему видно сразу. Анализ проекта превращает ошибки в план улучшений.","teams":"Команды: составьте анкету из 3 вопросов для участников нового ивента.","takeaway":"Ищите «узкое место» — оно тормозит весь проект."}],"homework":"Сделать онлайн-форму регистрации или афишу для нового ивента команды и показать её тренеру.","support":"Готовые пары «было — станет» для 3 типичных проблем (очередь, мало гостей, перерасход); ученик выбирает и дописывает ответственного.","advanced":"Добавить к каждому улучшению способ проверки (какая цифра покажет, что стало лучше) и рассчитать бюджет нового ивента с резервом 10%.","photo":{"src":"lessons/img/07_23.jpg","author":"Fujiphilm","q":["Что вы видите на фото? Как это связано с нашей темой?","Как сделать наш ивент полезным и доступным для всех учеников школы, включая младших?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l23.pptx","name":"23. Анализ проекта, новый ивент — практикум (7 кл).pptx","mb":1.6}},{"id":"07_24","g":7,"l":24,"topic":"Итоги ивента: доходы, расходы и результат в таблице","module":"Event-менеджмент","format":"Комбинированный","skills":["Финансовое мышление","Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет свести доходы и расходы ивента в таблицу, посчитать итог (прибыль или убыток) и объяснить, какая статья расходов повлияла на результат сильнее всего.","criteria":["Я правильно разношу суммы по колонкам «доходы» и «расходы».","Я верно считаю итог: доходы минус расходы.","Я объясняю результат и предлагаю, как его улучшить."],"result":"Финансовая таблица итогов ивента: доходы, расходы по статьям, итоговый результат и вывод из 2 предложений.","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Доход (income)","real":"Все деньги, которые ивент (event) получил: продажа билетов, товаров, взносы","shown":"Все деньги, которые ивент (event) получил: продажа билетов, товаров, взносы","truth":true,"first":"Д"},{"term":"Расходы (costs)","real":"Все деньги, потраченные на ивент: продукты, украшения, печать, призы","shown":"Какую часть от всех расходов занимает одна статья, в процентах","truth":false,"first":"Р"},{"term":"Статья расходов","real":"Группа однотипных трат, например «украшения»","shown":"Группа однотипных трат, например «украшения»","truth":true,"first":"С"},{"term":"Прибыль","real":"Сколько осталось, если доходы больше расходов","shown":"Все деньги, потраченные на ивент: продукты, украшения, печать, призы","truth":false,"first":"П"},{"term":"Убыток","real":"Сколько не хватило, если расходы больше доходов","shown":"Сколько не хватило, если расходы больше доходов","truth":true,"first":"У"},{"term":"Доля","real":"Какую часть от всех расходов занимает одна статья, в процентах","shown":"Сколько осталось, если доходы больше расходов","truth":false,"first":"Д"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Доход (income)","def":"Все деньги, которые ивент (event) получил: продажа билетов, товаров, взносы"},{"term":"Расходы (costs)","def":"Все деньги, потраченные на ивент: продукты, украшения, печать, призы"},{"term":"Статья расходов","def":"Группа однотипных трат, например «украшения»"},{"term":"Прибыль","def":"Сколько осталось, если доходы больше расходов"},{"term":"Убыток","def":"Сколько не хватило, если расходы больше доходов"},{"term":"Доля","def":"Какую часть от всех расходов занимает одна статья, в процентах"}],"english":"costs — расходы; income — доход; event — мероприятие","concepts":{"head":"Понятия","items":["У каждого ивента (event) есть доходы (income) и расходы (costs).","Итог = доходы − расходы.","Если итог больше нуля — прибыль, меньше нуля — убыток, ноль — «вышли в ноль»."]},"steps":{"head":"Как свести итоги, по шагам","items":["Собрать все чеки и записи кассы","Разнести суммы: доходы в одну колонку, расходы по статьям в другую","Сложить каждую колонку","Вычесть расходы из доходов","Посчитать долю самой большой статьи: статья ÷ все расходы × 100%","Сделать вывод"]},"scheme":"Таблица из двух колонок «Доходы | Расходы», внизу строка «Итого», под ней формула «Итог = Доходы − Расходы» и значок «+ прибыль / − убыток».","examples":[{"lab":"Казахстанский","text":"Ярмарка 7 класса в Семее. Доходы: выпечка 12 000 условных тенге, чай 4 000, лотерея 3 000 — всего 19 000. Расходы: продукты 7 000, стаканы 1 500, украшения 4 500, призы 3 000 — всего 16 000. Итог: 19 000 − 16 000 = 3 000 прибыли. Доля украшений: 4 500 ÷ 16 000 × 100% ≈ 28%."},{"lab":"Мировой","text":"Крупные музыкальные фестивали публикуют, что основная часть доходов — билеты, а большие расходы — сцена, звук и гонорары артистов."}],"mistake":{"myth":"Ученики путают выручку и прибыль и говорят «заработали 19 000»","fix":"Покажите, что 16 000 уже потрачено, и попросите назвать, сколько реально осталось."},"check":[{"q":"Деньги, взятые в долг у родительского комитета, — это доход?","a":"Нет, их нужно вернуть; это не заработок"},{"q":"Как найти самую «тяжёлую» статью?","a":"Сравнить суммы или доли"},{"q":"Если итог −500, что это значит?","a":"Убыток 500 условных тенге"}],"kz":{"text":"Кондитерская фабрика «Рахат». Алматинская фабрика «Рахат» работает с 1942 года и производит конфеты и шоколад, известные по всему Казахстану.","link":"любая компания, как и ярмарка, сравнивает доходы от продаж и расходы на сырьё, упаковку и доставку."},"world":{"text":"ЦУР ООН № 12 «Ответственное потребление и производство» призывает тратить ресурсы разумно. Многие мировые фестивали считают не только деньги, но и мусор после ивента и уменьшают одноразовую посуду.","link":""},"fact":"Двойную запись — способ учёта, где каждая операция отражается в двух местах, — впервые подробно описал итальянский математик Лука Пачоли в книге 1494 года. Поэтому его называют «отцом бухгалтерского учёта».","cards":[{"n":"1","title":"Доход или расход?","lines":["Задание: распределите по колонкам: продажа выпечки 12 000; покупка муки и сахара 7 000; лотерея 3 000; стаканы 1 500; продажа чая 4 000; гирлянды 4 500; призы 3 000."],"hand":"Сдать: таблицу с суммами по колонкам и итогом","answers":[["","Доходы 19 000, расходы 16 000, итог +3 000"]]},{"n":"2","title":"Итоги двух ярмарок","lines":["Вариант А.","Доходы: выпечка 15 000, чай 5 000, поделки 6 000.","Расходы: продукты 8 000, украшения 3 000, материалы для поделок 4 000, печать 1 000.","Вариант Б.","Доходы: выпечка 9 000, чай 2 000.","Расходы: продукты 6 000, украшения 5 000, аренда колонки 1 200.","Задание: для каждого варианта заполните таблицу, посчитайте итог, найдите долю самой большой статьи расходов и напишите вывод из 2 предложений."],"hand":"Сдать: таблицы и выводы. Ключ: А — доходы 26 000, расходы 16 000, итог +10 000, продукты 50%; Б — доходы 11 000, расходы 12 200, итог −1 200, продукты ≈49%.","answers":[]},{"n":"3","title":"Открытка из будущего","lines":["Задание: «Через три месяца я легко считаю итоги любого проекта, потому что … Действие на 48 часов: …»"],"hand":"Сдать: вслух только действие.","answers":[]}],"practice":[{"type":"case","title":"Олимпиада, за которую платили 30 лет","minutes":9,"source":"Летние Олимпийские игры в Монреале, Канада, 1976","hook":"Город провёл Олимпиаду. А потом десятилетиями платил долги.","story":["Монреаль готовился к Олимпиаде 1976 года, но строительство шло с задержками, а цены росли.","Стадион не успели полностью достроить к играм.","Расходы оказались во много раз больше доходов."],"question":"Как долго, по-вашему, город расплачивался за Олимпиаду?","options":["Олимпиада принесла прибыль","Год","Около 30 лет — долг за стадион погасили только в 2006 году","Долг простили на следующий день"],"answerIndex":2,"reveal":"Долг за Олимпийский стадион Монреаль окончательно выплатил лишь в 2006 году — через 30 лет. Если не вести таблицу доходов и расходов и не сравнивать её с планом, проект может стать огромным убытком.","teams":"Команды: составьте таблицу итогов прошлого ивента: доходы, расходы, результат. Где отклонения от плана?","takeaway":"Таблица доходов и расходов показывает правду о проекте."},{"type":"case","title":"Олимпиада с прибылью","minutes":8,"source":"Летние Олимпийские игры в Лос-Анджелесе, США, 1984, организатор Питер Юберрот","hook":"После Монреаля города боялись Олимпиад. Как Лос-Анджелес заработал?","story":["После Монреаля почти ни один город не хотел проводить Олимпиаду 1984 года.","Организатор Питер Юберрот решил: почти ничего нового не строить, а использовать стадионы, которые уже есть.","Деньги брали у спонсоров и за телетрансляции, считали каждую трату."],"question":"Чем закончилась Олимпиада 1984 года?","options":["Её перенесли в другой город","Огромными долгами","Прибылью — впервые за долгое время","Её отменили"],"answerIndex":2,"reveal":"Игры в Лос-Анджелесе закончились прибылью. Секрет — строгий контроль расходов и новые источники доходов: спонсоры и телевидение. Таблица «доходы — расходы» была главным инструментом организаторов.","teams":"Команды: найдите в вашем ивенте 2 способа сократить расходы и 1 новый источник дохода.","takeaway":"Используй то, что уже есть, и считай каждую трату."}],"homework":"Составить таблицу доходов и расходов для придуманного ивента (5 статей расходов, 2 источника доходов) и посчитать итог; суммы — только условные тенге.","support":"Таблица с уже разнесёнными колонками: ученик только складывает и вычитает; подсказка-формула на полях.","advanced":"Рассчитать, сколько нужно продать дополнительных стаканов чая по 200 условных тенге, чтобы перекрыть убыток в варианте Б Карточки 2.","photo":{"src":"lessons/img/07_24.jpg","author":"Alexander Mils","q":["Что вы видите на фото? Как это связано с нашей темой?","Какую статью расходов нашей ярмарки можно уменьшить, чтобы было и дешевле, и экологичнее?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l24.pptx","name":"24. Итоги ивента — доходы, расходы и результат в таблице (7 кл).pptx","mb":1.5}},{"id":"07_25","g":7,"l":25,"topic":"Сценарий ивента класса","module":"Event-менеджмент","format":"Комбинированный","skills":["Лидерство","Креативность","Командная работа"],"goal":"К концу урока команда сможет написать сценарий своего ивента (ярмарки или выбранного мероприятия) с SMART-целью и таймингом по минутам, в котором сумма блоков равна общему времени ивента.","criteria":["Я формулирую цель ивента по SMART.","Я расписываю программу по блокам с таймингом, и сумма минут совпадает с длительностью ивента.","Я указываю, кто ведёт каждый блок."],"result":"Сценарий ивента команды: SMART-цель, 6–8 блоков программы с таймингом по минутам и ответственными.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Ивент (event)","real":"Мероприятие с целью, гостями и программой","shown":"Мероприятие с целью, гостями и программой","truth":true,"first":"И"},{"term":"Сценарий (script)","real":"Пошаговый план ивента: что происходит, во сколько, сколько минут и кто отвечает","shown":"Человек, который объявляет блоки и держит темп ивента","truth":false,"first":"С"},{"term":"Тайминг","real":"Расписание по минутам","shown":"Расписание по минутам","truth":true,"first":"Т"},{"term":"SMART-цель","real":"Цель, которая конкретна, измерима, достижима, важна и ограничена сроком","shown":"Пошаговый план ивента: что происходит, во сколько, сколько минут и кто отвечает","truth":false,"first":"S"},{"term":"Диаграмма Ганта","real":"Таблица-график, где задачи показаны полосками по дням","shown":"Таблица-график, где задачи показаны полосками по дням","truth":true,"first":"Д"},{"term":"Ведущий","real":"Человек, который объявляет блоки и держит темп ивента","shown":"Цель, которая конкретна, измерима, достижима, важна и ограничена сроком","truth":false,"first":"В"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Ивент (event)","def":"Мероприятие с целью, гостями и программой"},{"term":"Сценарий (script)","def":"Пошаговый план ивента: что происходит, во сколько, сколько минут и кто отвечает"},{"term":"Тайминг","def":"Расписание по минутам"},{"term":"SMART-цель","def":"Цель, которая конкретна, измерима, достижима, важна и ограничена сроком"},{"term":"Диаграмма Ганта","def":"Таблица-график, где задачи показаны полосками по дням"},{"term":"Ведущий","def":"Человек, который объявляет блоки и держит темп ивента"}],"english":"event — мероприятие; script — сценарий","concepts":{"head":"Понятия","items":["Сценарий (script) отвечает на вопросы: что, когда, сколько минут, кто.","Он опирается на SMART-цель ивента (event): S — конкретная, M — измеримая, A — достижимая, R — важная, T — со сроком.","Подготовку к ивенту удобно показать на диаграмме Ганта, а сам день ивента — в сценарии с таймингом."]},"steps":{"head":"Как писать сценарий, по шагам","items":["Записать SMART-цель","Определить начало и конец (например, 14:00–15:30, это 90 минут)","Разбить на блоки: сбор гостей, открытие, основная часть, перерыв, финал, уборка","Дать каждому блоку минуты","Проверить сумму","Назначить ведущего и ответственных; ж) добавить 5 минут запаса"]},"scheme":"Таблица «Время — Блок — Минуты — Что происходит — Ответственный», внизу строка «Сумма минут = длительность».","examples":[{"lab":"Казахстанский","text":"Ярмарка 7 класса в Уральске, 14:00–15:30. SMART-цель: «20 декабря за 90 минут принять 60 гостей и продать товаров на 20 000 условных тенге». Блоки: 14:00–14:10 сбор гостей; 14:10–14:15 открытие; 14:15–15:00 торговля; 15:00–15:10 лотерея; 15:10–15:20 подсчёт и награждение; 15:20–15:30 уборка. Сумма: 10+5+45+10+10+10 = 90 минут."},{"lab":"Мировой","text":"Церемонии открытия Олимпийских игр расписаны по секундам, у каждого блока есть свой режиссёр."}],"mistake":{"myth":"Блоки не помещаются во время — сумма больше длительности","fix":"Сложите минуты вместе с классом и решите, какой блок сократить."},"check":[{"q":"«Провести классный ивент» — SMART-цель?","a":"Нет, нельзя измерить и нет срока"},{"q":"Зачем запас 5 минут?","a":"Ивенты почти всегда задерживаются"},{"q":"Как проверить тайминг?","a":"Сложить минуты всех блоков"}],"kz":{"text":"Празднование Наурыза в городах Казахстана. Каждый год 21–23 марта в городах проходят праздничные программы: концерты, ярмарки, угощение наурыз-коже. У организаторов есть сценарий с таймингом и ответственными за каждую площадку.","link":""},"world":{"text":"Церемонии открытия Олимпийских игр смотрят сотни миллионов людей по всему миру, и каждая расписана по минутам: выход команд, выступления, зажжение огня. Если один блок затянется, сдвигается прямая трансляция.","link":""},"fact":"Диаграмму Ганта придумал американский инженер Генри Гант в 1910-х годах, а позже её использовали при планировании крупных строек, например плотины Гувера в США в 1930-х.","cards":[{"n":"1","title":"SMART или нет?","lines":["Задание: отметьте SMART-цели: 1) «Сделать весёлую ярмарку». 2) «20 декабря с 14:00 до 15:30 принять 60 гостей и продать товаров на 20 000 условных тенге». 3) «Собрать много денег». 4) «До 15 декабря подготовить 80 пирожков для ярмарки»."],"hand":"Сдать: номера SMART-целей","answers":[["","2 и 4"]]},{"n":"2","title":"Сценарий нашего ивента","lines":["Данные: ивент длится 90 минут (14:00–15:30), гостей ждём 60, в команде 5 человек. Обязательные блоки: сбор гостей, открытие, основная часть, перерыв или конкурс, финал, уборка.","Задание: напишите SMART-цель и таблицу «Время — Блок — Минуты — Что происходит — Ответственный» на 6–8 блоков. Проверьте, что сумма равна 90 минутам, и отметьте 5 минут запаса."],"hand":"Сдать: сценарий на А4.","answers":[]},{"n":"3","title":"Открытка из будущего","lines":["Задание: «Через три месяца гости вспоминают наш ивент, потому что … Действие на 48 часов: …»"],"hand":"Сдать: вслух только действие.","answers":[]}],"practice":[{"type":"case","title":"Три устройства в одном","minutes":9,"source":"Презентация первого iPhone, Стив Джобс, январь 2007","hook":"Одна из самых известных презентаций в истории. Как построен её сценарий?","story":["9 января 2007 года Стив Джобс вышел на сцену и сказал, что сегодня Apple покажет три революционных устройства: плеер, телефон и интернет-коммуникатор.","Он повторял: «плеер, телефон, интернет… плеер, телефон, интернет…».","А потом сказал: «Вы поняли? Это не три устройства. Это одно устройство. И мы назовём его iPhone»."],"question":"Что, по-вашему, делает этот сценарий таким сильным?","options":["Интрига, повторение и неожиданный поворот в нужный момент","Громкая музыка","Очень длинный рассказ о характеристиках","Много слайдов с текстом"],"answerIndex":0,"reveal":"Сценарий был выверен до секунды и отрепетирован много раз. Интрига в начале, повторение и поворот сделали момент незабываемым. Хороший сценарий ивента тоже строится на ожидании и кульминации.","teams":"Команды: напишите сценарий ивента класса по минутам: открытие, интрига, кульминация, финал.","takeaway":"Сильный сценарий строится вокруг одного главного момента."},{"type":"case","title":"Сценарий выпускного «Посвящение»","minutes":8,"source":"Условная ситуация","hook":"Ивент длится час, но ведущий не знает, что после чего идёт.","story":["7 класс проводит «Посвящение в пятиклассники».","Есть идеи: конкурсы, песня, вручение значков, чаепитие. Но нет сценария по минутам.","В день ивента музыка не включилась, конкурс затянулся на 30 минут, а на значки времени не осталось."],"question":"Что спасло бы ивент?","options":["Сценарий по минутам с ответственными за каждый блок","Более громкая музыка","Больше конкурсов","Другой ведущий"],"answerIndex":0,"reveal":"Сценарий — это таблица: время, блок, кто отвечает, что нужно. Тогда видно, что конкурс должен длиться 10 минут, а за музыку отвечает конкретный человек.","teams":"Команды: составьте таблицу сценария: время — блок — ответственный — реквизит.","takeaway":"Сценарий по минутам с ответственными — основа ивента."}],"homework":"Дописать сценарий: добавить слова ведущего для открытия и финала (по 3–4 предложения) и запасной блок на 5 минут.","support":"Шаблон сценария с готовыми названиями блоков и подсказкой минут; ученику нужно вписать содержание и ответственных.","advanced":"Составить диаграмму Ганта подготовки к ивенту на 2 недели и связать её со сценарием: какие задачи должны быть готовы к каждому блоку.","photo":{"src":"lessons/img/07_25.jpg","author":"Fujiphilm","q":["Что вы видите на фото? Как это связано с нашей темой?","Что общего у сценария Олимпиады и нашей ярмарки?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l25.pptx","name":"25. Сценарий ивента класса (7 кл).pptx","mb":1.6}},{"id":"07_26","g":7,"l":26,"topic":"Ярмарка: ответственные и чек-лист","module":"Event-менеджмент","format":"Симуляция, ярмарка","skills":["Лидерство","Работа с клиентом","Финансовое мышление"],"goal":"К концу урока ученик сможет выполнить свою роль на учебной ярмарке по личному чек-листу и показать, за какие задачи он отвечал и что выполнил.","criteria":["Я знаю свою роль и выполняю все пункты своего чек-листа.","Я веду учёт продаж в условных тенге без ошибок.","Я помогаю команде, если в цепочке возникает «узкое место»."],"result":"План команды на ярмарку (товар, цена, роли, оформление) с таблицей ответственных и личными чек-листами, а также подсчёт выручки и прибыли команды после торговли.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Ярмарка (fair)","real":"Ивент (event), на котором команды продают свои товары покупателям","shown":"Ивент (event), на котором команды продают свои товары покупателям","truth":true,"first":"Я"},{"term":"Ответственность (responsibility)","real":"Обязанность выполнить свою задачу и отвечать за результат","shown":"Выручка минус расходы","truth":false,"first":"О"},{"term":"Ответственный","real":"Человек, за которым закреплена задача","shown":"Человек, за которым закреплена задача","truth":true,"first":"О"},{"term":"Чек-лист","real":"Список действий, где каждый пункт отмечают после выполнения","shown":"Обязанность выполнить свою задачу и отвечать за результат","truth":false,"first":"Ч"},{"term":"Выручка","real":"Все деньги от продаж","shown":"Все деньги от продаж","truth":true,"first":"В"},{"term":"Прибыль","real":"Выручка минус расходы","shown":"Список действий, где каждый пункт отмечают после выполнения","truth":false,"first":"П"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ярмарка (fair)","def":"Ивент (event), на котором команды продают свои товары покупателям"},{"term":"Ответственность (responsibility)","def":"Обязанность выполнить свою задачу и отвечать за результат"},{"term":"Ответственный","def":"Человек, за которым закреплена задача"},{"term":"Чек-лист","def":"Список действий, где каждый пункт отмечают после выполнения"},{"term":"Выручка","def":"Все деньги от продаж"},{"term":"Прибыль","def":"Выручка минус расходы"},{"term":"Узкое место","def":"Этап, где работа тормозится и задерживает всех"}],"english":"fair — ярмарка; responsibility — ответственность; event — мероприятие","concepts":{"head":"Понятия","items":["Ярмарка (fair) получается, когда у каждого есть своя ответственность (responsibility): ответственный за товар, кассир, продавец-консультант, оформитель, менеджер.","Чек-лист помогает ничего не забыть."]},"steps":{"head":"Как распределить работу, по шагам","items":["Выписать все задачи ярмарки","Назначить ответственного на каждую","Для каждой роли составить чек-лист из 4–5 пунктов «до, во время, после»","Договориться, кто кого заменяет","После ярмарки посчитать выручку и прибыль"]},"scheme":"Цепочка «Товар → Оформление → Продажа → Касса → Учёт», над каждым звеном — имя ответственного, под ним — 2 главных пункта чек-листа.","examples":[{"lab":"Казахстанский","text":"Команда 7 класса в Талдыкоргане продаёт закладки по 300 условных тенге и открытки по 500. Расходы на материалы — 2 000. Продали 10 закладок и 6 открыток: выручка 3 000 + 3 000 = 6 000, прибыль 6 000 − 2 000 = 4 000. Чек-лист кассира: проверить сдачу; записывать каждую продажу; сверить кассу каждые 10 минут; сдать итог менеджеру."},{"lab":"Мировой","text":"На рождественских ярмарках Европы у каждого домика есть продавец, кассир и ответственный за запасы."}],"mistake":{"myth":"Все продают, никто не считает, касса не сходится","fix":"Сравните записи учёта и деньги в кассе и покажите, где появилась разница."},"check":[{"q":"Что будет, если кассир не записывает продажи?","a":"Нельзя посчитать выручку и прибыль"},{"q":"Зачем замена?","a":"Если ответственный занят, работа не остановится"},{"q":"Чем выручка отличается от прибыли?","a":"Прибыль — после вычета расходов"}],"kz":{"text":"Базар «Зелёный базар» в Алматы. Один из самых известных рынков Казахстана, где сотни продавцов каждый день работают в одной системе: поставка товара, выкладка, продажа, расчёт.","link":"без ответственных и порядка такой рынок не смог бы работать."},"world":{"text":"Рождественские ярмарки в Германии и Австрии существуют несколько веков и привлекают туристов со всего мира; у каждого торгового домика чёткое распределение ролей. Многие ярмарки сегодня отказываются от одноразовой посуды ради экологии (ЦУР № 12).","link":""},"fact":"Сборочный конвейер Генри Форда, запущенный в 1913 году, сократил время сборки одного автомобиля Model T примерно с 12 часов до полутора часов, потому что каждый рабочий отвечал за одну операцию в цепочке.","cards":[{"n":"2","title":"План команды на ярмарку","lines":["Данные: стартовый бюджет команды 3 000 условных тенге. Материалы: бумага и картон 1 000, украшения 800, наклейки 600.","Задание: 1) Выберите товар (закладки, открытки, брелоки из бумаги) и цену. 2) Распределите роли: менеджер, кассир, продавец-консультант, оформитель, ответственный за товар. 3) Каждому — чек-лист из 4 пунктов «до / во время / после»."],"hand":"Сдать: таблицу «Задача — Ответственный — Замена» и чек-листы.","answers":[]},{"n":"3","title":"События рынка (тренер зачитывает)","lines":["1) Покупатель просит скидку за покупку 3 товаров. 2) У кассира закончилась сдача. 3) Конкуренты снизили цену на 100 условных тенге. 4) Пришёл «оптовый покупатель» и хочет 5 штук сразу.","Задание: команда за 30 секунд принимает решение, ответственный записывает его."],"hand":"Сдать: записанные решения вместе с учётом продаж.","answers":[]}],"practice":[{"type":"case","title":"Чек-лист в операционной","minutes":9,"source":"Контрольный список ВОЗ «Безопасная хирургия», Атул Гаванде и коллеги, 2008–2009","hook":"Опытные хирурги и простой лист из 19 пунктов. Что изменилось?","story":["Хирург Атул Гаванде вместе с ВОЗ составил короткий список проверки для операционной.","Перед операцией команда вслух проверяет простые вещи: тот ли пациент, какая операция, есть ли аллергия, все ли инструменты.","Список проверили в 8 больницах разных стран."],"question":"Что, по-вашему, показала проверка?","options":["Хирурги отказались от списка","Осложнений и смертей стало заметно меньше","Ничего не изменилось","Операции стали длиннее и хуже"],"answerIndex":1,"reveal":"В исследовании, опубликованном в 2009 году, после внедрения чек-листа осложнений и смертей стало заметно меньше. Даже профессионалы забывают простые вещи — список защищает от этого.","teams":"Команды: составьте чек-лист ярмарки из 10 пунктов с ответственным за каждый.","takeaway":"Чек-лист защищает от забывчивости даже профессионалов."},{"type":"case","title":"Самолёт, который «слишком сложен»","minutes":8,"source":"Испытания бомбардировщика Boeing Model 299, США, 1935","hook":"Лучший самолёт своего времени разбился на испытаниях. Почему?","story":["В 1935 году Boeing показывал армии новый самолёт Model 299 — самый современный в мире.","Во время показательного полёта самолёт разбился сразу после взлёта.","Выяснилось: опытный пилот забыл снять один фиксатор рулей — шагов перед взлётом стало слишком много."],"question":"Что придумали пилоты, чтобы такое не повторилось?","options":["Отказались от самолёта","Чек-лист пилота: проверка перед взлётом по списку","Наняли больше пилотов","Сделали самолёт проще"],"answerIndex":1,"reveal":"Пилоты составили короткие списки проверки перед взлётом, посадкой и запуском двигателей. С ними самолёт летал безопасно. Так в авиации появился чек-лист.","teams":"Команды: распределите ответственных: кто отвечает за кассу, товар, вывеску, уборку. Запишите в чек-лист.","takeaway":"Когда шагов много, их нельзя держать в голове — нужен список."}],"homework":"Записать, что получилось и что не получилось в своей роли на ярмарке, и предложить 1 пункт, который нужно добавить в чек-лист.","support":"Готовый чек-лист для каждой роли из 4 пунктов; ученику с трудностями дать роль с понятными действиями (оформитель, помощник кассира) и пару-наставника.","advanced":"Роль менеджера ярмарки: следить за узкими местами всех ролей, принимать решения по событиям рынка и посчитать, какая доля выручки пришлась на каждый товар.","photo":{"src":"lessons/img/07_26.jpg","author":"Nguyễn Đức","q":["Что вы видите на фото? Как это связано с нашей темой?","Какое правило ответственной торговли мы можем ввести на нашей ярмарке?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l26.pptx","name":"26. Ярмарка — ответственные и чек-лист (7 кл).pptx","mb":1.7}},{"id":"07_27","g":7,"l":27,"topic":"Сценарий ивента класса: прогон","module":"Event-менеджмент","format":"Комбинированный","skills":["Финансовое мышление","Лидерство","Критическое мышление"],"goal":"К концу урока команда сможет провести прогон сценария своего ивента, сравнить плановое и фактическое время каждого блока и исправить тайминг так, чтобы ивент укладывался в отведённое время.","criteria":["Я участвую в прогоне и выполняю свою роль по сценарию.","Я замеряю фактическое время блока и считаю разницу с планом.","Я предлагаю исправление тайминга, чтобы сумма снова совпала с длительностью ивента."],"result":"Протокол прогона: таблица «блок — план, мин — факт, мин — разница — исправление» и исправленный сценарий ивента.","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Сценарий (script)","real":"Пошаговый план ивента (event) с таймингом и ответственными","shown":"Пошаговый план ивента (event) с таймингом и ответственными","truth":true,"first":"С"},{"term":"Прогон","real":"Репетиция ивента по сценарию от начала до конца","shown":"Проверка оборудования: звук, свет, презентация","truth":false,"first":"П"},{"term":"Хронометраж","real":"Замер фактического времени каждого блока","shown":"Замер фактического времени каждого блока","truth":true,"first":"Х"},{"term":"План и факт","real":"Сколько минут запланировали и сколько получилось на деле","shown":"Репетиция ивента по сценарию от начала до конца","truth":false,"first":"П"},{"term":"Корректировка","real":"Исправление сценария после прогона","shown":"Исправление сценария после прогона","truth":true,"first":"К"},{"term":"Технический прогон","real":"Проверка оборудования: звук, свет, презентация","shown":"Сколько минут запланировали и сколько получилось на деле","truth":false,"first":"Т"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Сценарий (script)","def":"Пошаговый план ивента (event) с таймингом и ответственными"},{"term":"Прогон","def":"Репетиция ивента по сценарию от начала до конца"},{"term":"Хронометраж","def":"Замер фактического времени каждого блока"},{"term":"План и факт","def":"Сколько минут запланировали и сколько получилось на деле"},{"term":"Корректировка","def":"Исправление сценария после прогона"},{"term":"Технический прогон","def":"Проверка оборудования: звук, свет, презентация"}],"english":"event — мероприятие; script — сценарий","concepts":{"head":"Понятия","items":["Прогон — это репетиция ивента (event) по сценарию (script), чтобы найти слабые места до приезда гостей.","Хронометрист замеряет каждый блок, и команда сравнивает план и факт."]},"steps":{"head":"Как провести прогон, по шагам","items":["Раздать роли и сценарий","Назначить хронометриста и наблюдателя","Пройти блоки подряд без остановок","Записать факт по каждому блоку","Посчитать разницу «факт − план»","Решить, что сократить, ускорить или убрать; ж) записать исправленный сценарий"]},"scheme":"Таблица «Блок — План — Факт — Разница — Исправление», внизу строки «Сумма плана», «Сумма факта» и цель «Разница = 0».","examples":[{"lab":"Казахстанский","text":"Команда в Костанае репетирует новогодний концерт на 60 минут. План: открытие 5, номер 1 — 10, игра с залом 15, номер 2 — 10, награждение 10, финал 10. Факт: открытие 8, игра 20. Разница +3 и +5, всего +8 минут. Исправление: сократить игру до 12 минут и награждение до 5 — сумма снова 60."},{"lab":"Мировой","text":"Театры перед премьерой проводят генеральную репетицию в костюмах и со светом, чтобы проверить каждую минуту спектакля."}],"mistake":{"myth":"Команда во время прогона останавливается и обсуждает каждую мелочь, и прогон не доходит до конца","fix":"Правило «прогон без остановок, замечания — в конце»."},"check":[{"q":"Зачем прогон, если сценарий уже написан?","a":"На бумаге время всегда меньше, чем на деле"},{"q":"Что делать, если блок затянулся на 5 минут?","a":"Сократить другой блок или упростить этот"},{"q":"Кто следит за временем на самом ивенте?","a":"Хронометрист или ведущий"}],"kz":{"text":"Государственный академический театр оперы и балета «Астана Опера». Театр открылся в 2013 году и ставит большие спектакли с сотнями участников; перед каждой премьерой проходят генеральные репетиции с таймингом.","link":"даже профессионалы репетируют, чтобы уложиться во время."},"world":{"text":"Перед открытием чемпионатов мира по футболу организаторы проводят несколько полных прогонов церемонии на стадионе с волонтёрами вместо зрителей. Так находят проблемы с выходом артистов и временем трансляции.","link":""},"fact":"Слово «репетиция» происходит от латинского repetitio — «повторение». В театре традиция генеральной репетиции, то есть полного прогона перед премьерой, существует несколько столетий.","cards":[{"n":"1","title":"Разбор прогона","lines":["Данные концерта на 60 минут. План: открытие 5, номер 1 — 10, игра с залом 15, номер 2 — 10, награждение 10, финал 10. Факт: открытие 8, номер 1 — 10, игра 20, номер 2 — 9, награждение 10, финал 10.","Задание: посчитайте разницу по каждому блоку и общую, предложите исправление, чтобы уложиться в 60 минут."],"hand":"Сдать: таблицу","answers":[["","Факт 67 минут, разница +7"]]},{"n":"2","title":"Протокол нашего прогона","lines":["Роли: ведущий, участники блоков, хронометрист, наблюдатель (записывает заминки).","Задание: проведите ускоренный прогон вашего сценария (1 минута плана = 12 секунд прогона). Заполните таблицу «Блок — План — Факт — Разница — Исправление», запишите 2 заминки от наблюдателя."],"hand":"Сдать: протокол и исправленный сценарий.","answers":[]},{"n":"3","title":"Открытка из будущего","lines":["Задание: «Через три месяца наш ивент закончился минута в минуту, потому что … Действие на 48 часов: …»"],"hand":"Сдать: вслух только действие.","answers":[]}],"practice":[{"type":"case","title":"Генеральная репетиция у Луны","minutes":9,"source":"Полёт «Аполлон-10», NASA, май 1969","hook":"За два месяца до высадки на Луну астронавты долетели до неё — и не сели. Зачем?","story":["Перед высадкой «Аполлона-11» NASA отправила к Луне «Аполлон-10».","Экипаж выполнил почти всё, что нужно для посадки: облетел Луну, отделил лунный модуль и опустился примерно на 15 км над поверхностью.","Но садиться было запрещено — это была генеральная репетиция."],"question":"Зачем, по-вашему, нужна была такая репетиция?","options":["Потому что не хватило топлива","Проверить все шаги и найти проблемы до настоящей посадки","Сфотографировать Луну","Ради рекорда"],"answerIndex":1,"reveal":"Репетиция проверила технику, связь и действия экипажа. Проблемы, найденные на «Аполлоне-10», исправили, и в июле 1969 года «Аполлон-11» сел на Луну. Прогон ивента — та же генеральная репетиция.","teams":"Команды: проведите прогон сценария ивента по минутам. Найдите 3 места, где может что-то пойти не так.","takeaway":"Генеральная репетиция находит проблемы до премьеры."},{"type":"case","title":"Прогон за час до начала","minutes":8,"source":"Условная ситуация","hook":"Класс решил «прогнать» ивент прямо перед началом. Что пошло не так?","story":["Ивент начинался в 14:00. Прогон назначили на 13:00.","На прогоне выяснилось: проектор не подключается к ноутбуку, а ведущий не помнит слова.","Исправить за час не успели, ивент начался на 20 минут позже."],"question":"Когда лучше проводить прогон?","options":["За 5 минут до начала","За 1–2 дня, чтобы успеть исправить ошибки","Прогон не нужен","После ивента"],"answerIndex":1,"reveal":"Прогон нужен, чтобы найти и исправить ошибки. Если проводить его в последний момент, исправлять уже некогда. Лучше прогнать за 1–2 дня в том же зале и с той же техникой.","teams":"Команды: составьте план прогона: когда, где, кто, что проверяем.","takeaway":"Прогон проводят заранее, чтобы было время исправить."}],"homework":"Выучить свою часть сценария и прорепетировать её дома с таймером; записать, сколько минут заняло.","support":"Готовый протокол с заполненной колонкой «План»; ученик только записывает факт и считает разницу; роль хронометриста как понятная задача.","advanced":"Составить два варианта исправленного сценария (короткий на 45 минут и полный на 60 минут) и объяснить, какие блоки убираются в коротком.","photo":{"src":"lessons/img/07_27.jpg","author":"Fujiphilm","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие проблемы можно найти только на прогоне, а не на бумаге?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l27.pptx","name":"27. Сценарий ивента класса — прогон (7 кл).pptx","mb":1.6}},{"id":"07_28","g":7,"l":28,"topic":"Риски ивента: план Б","module":"Event-менеджмент","format":"Комбинированный","skills":["Лидерство","Принятие решений","Критическое мышление"],"goal":"К концу урока ученик сможет назвать 3 типичных риска своего ивента, объяснить, что такое план Б, и составить план Б для самого опасного риска с ответственным.","criteria":["Я называю 3 типичных риска ивента и оцениваю их вероятность и влияние.","Я объясняю своими словами, что такое план Б.","Я пишу план Б с конкретными действиями, ответственным и сигналом, когда его включать."],"result":"Карточка «План Б» для ивента команды: 3 риска с оценкой вероятности и влияния, план Б для главного риска и распределение обязанностей.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Ивент (event)","real":"Мероприятие с целью, гостями и программой","shown":"Мероприятие с целью, гостями и программой","truth":true,"first":"И"},{"term":"Риск (risk)","real":"Возможное событие, которое помешает или поможет ивенту","shown":"Насколько часто такое случается","truth":false,"first":"Р"},{"term":"План Б (plan B)","real":"Заранее подготовленный запасной вариант на случай, если основной план не сработает","shown":"Заранее подготовленный запасной вариант на случай, если основной план не сработает","truth":true,"first":"П"},{"term":"SMART-цель","real":"Конкретная, измеримая, достижимая, важная цель со сроком","shown":"Возможное событие, которое помешает или поможет ивенту","truth":false,"first":"S"},{"term":"Диаграмма Ганта","real":"График задач подготовки по дням","shown":"График задач подготовки по дням","truth":true,"first":"Д"},{"term":"Вероятность","real":"Насколько часто такое случается","shown":"Конкретная, измеримая, достижимая, важная цель со сроком","truth":false,"first":"В"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ивент (event)","def":"Мероприятие с целью, гостями и программой"},{"term":"Риск (risk)","def":"Возможное событие, которое помешает или поможет ивенту"},{"term":"План Б (plan B)","def":"Заранее подготовленный запасной вариант на случай, если основной план не сработает"},{"term":"SMART-цель","def":"Конкретная, измеримая, достижимая, важная цель со сроком"},{"term":"Диаграмма Ганта","def":"График задач подготовки по дням"},{"term":"Вероятность","def":"Насколько часто такое случается"},{"term":"Влияние","def":"Насколько сильно риск испортит ивент"}],"english":"risk — риск; event — мероприятие; plan — план","concepts":{"head":"Понятия","items":["Риск (risk) — возможное событие, которое помешает SMART-цели ивента (event).","План Б (plan B) — запасной план (plan), который готовят заранее, а включают только при сигнале."]},"steps":{"head":"Как готовить план Б, по шагам","items":["Брейнсторм рисков","Оценка по двум шкалам: вероятность (низкая/высокая) и влияние (слабое/сильное)","Выбираем риск «высокая вероятность + сильное влияние»","Пишем план Б: что делаем, кто отвечает, какие ресурсы нужны","Задаём сигнал включения («если ведущий не пришёл к 13:45…»)","Добавляем задачи плана Б в диаграмму Ганта"]},"scheme":"Квадрат 2×2 «Вероятность × Влияние»; в правом верхнем углу «План Б обязателен», в левом нижнем «Просто наблюдаем». Рядом карточка плана Б: «Если… (сигнал) → то… (действия) → кто → что нужно».","examples":[{"lab":"Казахстанский","text":"Команда в Атырау готовит уличную зимнюю игру 22 декабря. Риск: сильный мороз и ветер — высокая вероятность, сильное влияние. План Б: перенос в спортзал; ответственный договаривается со спортзалом за 3 дня; сигнал — прогноз ниже −20 °C накануне. Стоимость — 0 условных тенге, нужна только договорённость."},{"lab":"Мировой","text":"На открытых теннисных турнирах держат запасные крытые корты и раздвижные крыши на случай дождя."}],"mistake":{"myth":"План Б звучит как «что-нибудь придумаем»","fix":"Попросите заполнить все 4 части карточки «Если — то — кто — что нужно»."},"check":[{"q":"Когда включается план Б?","a":"Когда сработал заранее заданный сигнал"},{"q":"Нужен ли план Б на каждый риск?","a":"Нет, только на опасные: высокая вероятность и сильное влияние"},{"q":"Чем план Б отличается от импровизации?","a":"Он подготовлен заранее, и все знают свои действия"}],"kz":{"text":"Медеу в Алматы. Высокогорный каток «Медеу» принимает массовые катания и соревнования под открытым небом, поэтому организаторы всегда учитывают погоду и качество льда и имеют запасные решения на случай оттепели или снегопада.","link":""},"world":{"text":"В 1970 году экипаж космического корабля «Аполлон-13» вернулся на Землю после аварии благодаря запасным решениям, которые команда на Земле и астронавты нашли вместе. Эту историю приводят как пример силы плана Б и командной работы.","link":""},"fact":"В апреле 1970 года после взрыва кислородного баллона на «Аполлоне-13» астронавты использовали лунный модуль как «спасательную шлюпку», хотя он не был для этого задуман, и благополучно вернулись на Землю.","cards":[{"n":"1","title":"Квадрат рисков","lines":["Риски: 1) Сломался проектор. 2) Заболел ведущий. 3) Мороз ниже −20 °C в день уличной игры. 4) Пришло на 5 гостей меньше. 5) Закончились призы. 6) Метеорит упал на школу.","Задание: разместите риски в квадрате «Вероятность × Влияние» и отметьте, для каких нужен план Б."],"hand":"Сдать: квадрат с номерами рисков.","answers":[]},{"n":"2","title":"План Б нашего ивента","lines":["Задание: 1) Назовите 3 риска вашего ивента и поставьте их в квадрат. 2) Для самого опасного заполните: Сигнал «Если…» — Действия «то…» — Ответственный — Что нужно заранее (ресурсы, договорённости, условные тенге). 3) Распределите обязанности: кто сообщает команде, кто сообщает гостям."],"hand":"Сдать: карточку «План Б» на А4.","answers":[]},{"n":"3","title":"Открытка из будущего","lines":["Задание: «Через три месяца я спокойно справился с неожиданностью, потому что заранее … Действие на 48 часов: …»"],"hand":"Сдать: вслух только действие.","answers":[]}],"practice":[{"type":"case","title":"Вулкан закрыл небо Европы","minutes":9,"source":"Извержение вулкана Эйяфьядлайёкюдль, Исландия, апрель 2010","hook":"Вулкан в Исландии остановил самолёты по всей Европе. Как спасти поездку?","story":["В апреле 2010 года в Исландии началось извержение вулкана Эйяфьядлайёкюдль.","Облако вулканического пепла накрыло Европу, и почти все полёты отменили почти на неделю.","Миллионы людей застряли в аэропортах, отменились конференции и концерты."],"question":"Что, по-вашему, помогло тем, у кого был план Б?","options":["Ожидание в аэропорту","Заранее известные запасные варианты: поезд, автобус, перенос, онлайн","Ничего не помогло","Жалобы в авиакомпанию"],"answerIndex":1,"reveal":"У кого был запасной план, тот пересел на поезда и автобусы или провёл встречи онлайн. Риск, который невозможно предсказать точно, всё равно можно подготовить: «если не получится X — делаем Y».","teams":"Команды: составьте таблицу рисков ивента: риск — вероятность — что делаем (план Б).","takeaway":"План Б готовят заранее, когда всё ещё спокойно."},{"type":"case","title":"Ярмарка под дождём","minutes":8,"source":"Условная ситуация","hook":"Ярмарку планировали во дворе. В прогнозе — дождь.","story":["7 класс готовит ярмарку во дворе школы: 8 столов, музыка, гирлянды.","За два дня прогноз показывает 70% вероятность дождя.","Свободен только спортзал, но там в это время тренировка."],"question":"Какой план Б лучше?","options":["Отменить ярмарку","Заранее договориться о холле или коридоре и решить, когда переезжаем","Надеяться, что дождя не будет","Провести под дождём"],"answerIndex":1,"reveal":"Хороший план Б: запасное место заранее, точный «сигнал» для переезда (например, решение в 8:00 по прогнозу) и ответственный за переезд.","teams":"Команды: для 3 рисков ярмарки напишите сигнал, план Б и ответственного.","takeaway":"План Б = запасной вариант + сигнал + ответственный."}],"homework":"Подготовить для плана Б всё, что можно сделать заранее (договориться о запасном месте, найти запасного ведущего), и отчитаться команде.","support":"Список из 6 типичных рисков ивента с подсказкой, куда их поставить в квадрате; шаблон «Если …, то …, отвечает …».","advanced":"Составить план Б для позитивного риска (пришло вдвое больше гостей) и посчитать, сколько дополнительных условных тенге на него нужно.","photo":{"src":"lessons/img/07_28.jpg","author":"Erik Witsoe","q":["Что вы видите на фото? Как это связано с нашей темой?","Что помогло команде не растеряться в критической ситуации?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l28.pptx","name":"28. Риски ивента — план Б (7 кл).pptx","mb":1.5}},{"id":"07_29","g":7,"l":29,"topic":"После ярмарки: что пошло не по плану","module":"Event-менеджмент","format":"Симуляция, ярмарка","skills":["Лидерство","Принятие решений","Работа с клиентом"],"goal":"К концу урока ученик сможет разобрать итоги ярмарки по цифрам и наблюдениям: назвать 2 отклонения от плана, их причины и проверить одно улучшение на повторной мини-ярмарке.","criteria":["Я сравниваю план и факт ярмарки в цифрах и нахожу отклонения.","Я называю причину отклонения, опираясь на наблюдения, а не на догадки.","Я проверяю одно улучшение на мини-ярмарке и говорю, сработало ли оно."],"result":"Расчёт выручки и прибыли (план и факт) и лист «Что сработало / что улучшить» с результатом проверки улучшения на мини-ярмарке.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Ярмарка (fair)","real":"Ивент (event), где команды продают товары покупателям","shown":"Ивент (event), где команды продают товары покупателям","truth":true,"first":"Я"},{"term":"План (plan) и факт","real":"Что задумали и что получилось на самом деле","shown":"То, что заметили своими глазами: очередь, вопросы покупателей, пустой прилавок","truth":false,"first":"П"},{"term":"Отклонение","real":"Разница между планом и фактом","shown":"Разница между планом и фактом","truth":true,"first":"О"},{"term":"Выручка","real":"Все деньги от продаж","shown":"Что задумали и что получилось на самом деле","truth":false,"first":"В"},{"term":"Прибыль","real":"Выручка минус расходы","shown":"Выручка минус расходы","truth":true,"first":"П"},{"term":"Наблюдение","real":"То, что заметили своими глазами: очередь, вопросы покупателей, пустой прилавок","shown":"Все деньги от продаж","truth":false,"first":"Н"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Ярмарка (fair)","def":"Ивент (event), где команды продают товары покупателям"},{"term":"План (plan) и факт","def":"Что задумали и что получилось на самом деле"},{"term":"Отклонение","def":"Разница между планом и фактом"},{"term":"Выручка","def":"Все деньги от продаж"},{"term":"Прибыль","def":"Выручка минус расходы"},{"term":"Наблюдение","def":"То, что заметили своими глазами: очередь, вопросы покупателей, пустой прилавок"}],"english":"fair — ярмарка; event — мероприятие; plan — план","concepts":{"head":"Понятия","items":["После ярмарки (fair) сравниваем план (plan) и факт.","Отклонение = факт − план.","Отклонение может быть в выручке, количестве проданного, времени, числе покупателей."]},"steps":{"head":"Как разбирать, по шагам","items":["Выписать плановые цифры","Выписать фактические цифры из учёта","Посчитать отклонения","К каждому большому отклонению найти причину по наблюдениям","Записать «что сработало» и «что улучшить»","Проверить одно улучшение на практике"]},"scheme":"Таблица «Показатель — План — Факт — Отклонение — Причина», рядом две колонки «Сработало / Улучшить» и стрелка «Проверка на мини-ярмарке».","examples":[{"lab":"Казахстанский","text":"Команда в Петропавловске планировала продать 20 открыток по 500 условных тенге (выручка 10 000), продала 12 (6 000). Расходы 3 000, плановая прибыль 7 000, фактическая 3 000. Отклонение выручки −4 000. Наблюдения: открытки стояли в коробке, покупатели их не видели; у соседей была выкладка на стенде. Улучшение: выставить образцы и ценники."},{"lab":"Мировой","text":"Сети магазинов проверяют выкладку товаров и сравнивают продажи до и после изменения."}],"mistake":{"myth":"Причины «покупатели плохие» или «нам не повезло»","fix":"Попросите найти причину, которую команда может изменить сама."},"check":[{"q":"Отклонение −4 000 — это прибыль или выручка?","a":"Выручка; прибыль упала на 4 000 тоже, так как расходы те же"},{"q":"Почему важны наблюдения?","a":"Цифры показывают что, наблюдения — почему"},{"q":"Как проверить улучшение?","a":"Попробовать и сравнить результат"}],"kz":{"text":"Magnum Cash & Carry. Крупнейшая казахстанская сеть продуктовых магазинов работает во многих городах страны; такие сети постоянно сравнивают план и факт продаж и меняют выкладку, ассортимент и акции.","link":"разбор «что пошло не по плану» — обычная работа любой торговой компании."},"world":{"text":"Компания IKEA известна тем, что тщательно продумывает, как покупатель проходит по магазину и видит товар, и проверяет изменения выкладки на продажах.","link":""},"fact":"Первые тележки для покупок в супермаркете придумал американский владелец магазинов Сильван Голдман в 1937 году: он заметил, что покупатели перестают брать товары, когда корзина становится тяжёлой. Наблюдение за покупателями помогло увеличить продажи.","cards":[{"n":"1","title":"План и факт","lines":["Пример: план — 20 открыток по 500 условных тенге, расходы 3 000; факт — продано 12. Наблюдения: открытки в коробке, у соседей стенд с образцами.","Задание: 1) Посчитайте плановую и фактическую выручку и прибыль, отклонения (ответ: выручка 10 000 и 6 000, прибыль 7 000 и 3 000, отклонение −4 000). 2) Заполните такую же таблицу для своей ярмарки. 3) Выберите одно улучшение для проверки."],"hand":"Сдать: таблицу и улучшение.","answers":[]},{"n":"2","title":"События мини-ярмарки","lines":["1) Покупатель спрашивает, из чего сделан товар. 2) Конкурент проводит акцию «2 по цене 1,5». 3) Пришла группа из 5 покупателей одновременно. 4) Покупатель хочет вернуть товар.","Задание: за 30 секунд решите, как действовать, и запишите решение."],"hand":"Сдать: решения вместе с учётом продаж.","answers":[]},{"n":"3","title":"Открытка из будущего","lines":["Задание: «Через три месяца наша следующая ярмарка прошла по плану, потому что … Действие на 48 часов: …»"],"hand":"Сдать: вслух только действие.","answers":[]}],"practice":[{"type":"case","title":"Крышка с номером 349","minutes":9,"source":"Акция Pepsi «Number Fever», Филиппины, 1992","hook":"Акция с призом в 1 миллион песо. Что пошло не так?","story":["В 1992 году Pepsi на Филиппинах устроила акцию: под крышками были номера, и обладатель «счастливого» номера получал до 1 миллиона песо.","Однажды вечером объявили выигрышный номер — 349.","Оказалось, из-за ошибки этот номер напечатали на сотнях тысяч крышек."],"question":"Что, по-вашему, было главной ошибкой в подготовке акции?","options":["Слишком большой приз","Неправильная страна","Плохой вкус напитка","Не проверили систему печати номеров и не продумали риск ошибки"],"answerIndex":3,"reveal":"Сотни тысяч людей пришли за выигрышем, начались протесты, компания долго разбиралась в судах. Одна непроверенная деталь превратила акцию в кризис. После ярмарки тоже важно найти «точку, где всё сломалось».","teams":"Команды: найдите в итогах своей ярмарки, что пошло не по плану, и найдите причину — где это можно было заметить раньше?","takeaway":"Ищите момент, где ошибку можно было заметить раньше."},{"type":"case","title":"Сдача кончилась в первые 10 минут","minutes":8,"source":"Условная ситуация","hook":"Ярмарка только началась, а продавать нечем — нет сдачи.","story":["Команда продавала кексы по 400 тенге. Почти все покупатели платили купюрами 2 000 и 5 000 тенге.","Через 10 минут мелочь закончилась, и половине покупателей пришлось отказать.","К концу ярмарки осталось 20 непроданных кексов."],"question":"Что нужно было сделать по-другому?","options":["Печь меньше кексов","Заранее подготовить разменные деньги и принимать переводы","Поднять цену","Продавать только друзьям"],"answerIndex":1,"reveal":"Нехватка сдачи — частая ошибка ярмарок. Её легко предусмотреть: разменный фонд и оплата переводом. Разбор после ярмарки превращает такие мелочи в пункты чек-листа.","teams":"Команды: допишите в чек-лист следующей ярмарки 3 пункта по итогам разбора.","takeaway":"Ошибки ярмарки становятся пунктами будущего чек-листа."}],"homework":"Написать «письмо команде следующего года» из 5 предложений: что сработало на ярмарке, что улучшить и какой совет главный.","support":"Таблица с заполненными плановыми цифрами и подсказками причин (выкладка, цена, очередь, реклама); ученик выбирает и подтверждает наблюдением.","advanced":"Посчитать отклонение в процентах от плана по выручке и прибыли и сравнить, у какой команды отклонение меньше и почему.","photo":{"src":"lessons/img/07_29.jpg","author":"Towfiqu barbhuiya","q":["Что вы видите на фото? Как это связано с нашей темой?","Что из опыта больших магазинов можно применить к прилавку на школьной ярмарке?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l29.pptx","name":"29. После ярмарки — что пошло не по плану (7 кл).pptx","mb":1.4}},{"id":"07_30","g":7,"l":30,"topic":"Итоговая работа за полугодие (Рефлексивное занятие)","module":"Event-менеджмент","format":"Итоговая работа","skills":["Лидерство","Критическое мышление"],"goal":"К концу урока ученик сможет выполнить итоговую работу по модулю «Event-менеджмент»: правильно ответить не менее чем на 7 из 10 вопросов по терминам и решить практическое задание по ивенту (риски, график, бюджет).","criteria":["Я выполняю задания по темам модуля: термины, риски, тайминг, бюджет.","Я объясняю свои решения в практическом задании.","Я оцениваю свой результат по чек-листу самопроверки."],"result":"Итоговая работа: тест из 10 вопросов по терминам и практическое задание «Мини-проект ивента» (SMART-цель, 3 риска с планом, тайминг, таблица доходов и расходов).","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Ивент (event)","real":"Мероприятие с целью, гостями и программой","shown":"Мероприятие с целью, гостями и программой","truth":true,"first":"И"},{"term":"Повторение (review)","real":"Возвращение к изученному, чтобы закрепить его","shown":"План ивента по минутам с ответственными","truth":false,"first":"П"},{"term":"SMART-цель","real":"Конкретная, измеримая, достижимая, важная цель со сроком","shown":"Конкретная, измеримая, достижимая, важная цель со сроком","truth":true,"first":"S"},{"term":"Риск","real":"Возможное событие, которое повлияет на ивент; план Б — запасной вариант","shown":"Возвращение к изученному, чтобы закрепить его","truth":false,"first":"Р"},{"term":"Дедлайн","real":"Последний срок выполнения задачи","shown":"Последний срок выполнения задачи","truth":true,"first":"Д"},{"term":"Сценарий","real":"План ивента по минутам с ответственными","shown":"Возможное событие, которое повлияет на ивент; план Б — запасной вариант","truth":false,"first":"С"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ивент (event)","def":"Мероприятие с целью, гостями и программой"},{"term":"Повторение (review)","def":"Возвращение к изученному, чтобы закрепить его"},{"term":"SMART-цель","def":"Конкретная, измеримая, достижимая, важная цель со сроком"},{"term":"Риск","def":"Возможное событие, которое повлияет на ивент; план Б — запасной вариант"},{"term":"Дедлайн","def":"Последний срок выполнения задачи"},{"term":"Сценарий","def":"План ивента по минутам с ответственными"},{"term":"Прибыль","def":"Доходы минус расходы"}],"english":"event — мероприятие; review — повторение","concepts":{"head":"Базовые понятия модуля","items":["ивент (event), проект, менеджер проекта, SMART-цель, диаграмма Ганта, риск и план Б, конфликт (задач, ценностей, отношений), дедлайн, сценарий и тайминг, доходы, расходы, прибыль, анализ проекта."]},"steps":{"head":"Как выполнять работу, по шагам","items":["Прочитать все задания","Сначала тест (10–12 минут)","Затем практическое задание (15 минут)","Оставить 1–2 минуты на проверку арифметики"]},"scheme":"Путь ивента «Цель (SMART) → План и дедлайны (Ганта) → Риски и план Б → Сценарий и тайминг → Проведение → Итоги: доходы − расходы → Анализ». Схема висит во время работы как опора.","examples":[{"lab":"Казахстанский","text":"Ярмарка в Шымкенте — доходы 18 000 условных тенге, расходы 11 000, прибыль 7 000."},{"lab":"Мировой","text":"Fyre Festival 2017 провалился из-за неуправляемых рисков."}],"mistake":{"myth":"Ученики теряют время на одном трудном вопросе теста","fix":"Правило «пропусти и вернись», отметить вопрос звёздочкой. Оценивание: тест — 10 баллов (по 1 за вопрос), практика — 10 баллов (SMART-цель 2, риски и план 3, тайминг 2, расчёт 3); итог переводится в балл 1–10 и идёт в 30% индекса «Лидер бизнеса»."},"check":[{"q":"«Подготовить классный ивент» — SMART-цель?","a":"Нет"},{"q":"Что включается при сработавшем сигнале?","a":"План Б"},{"q":"Как найти прибыль?","a":"Доходы − расходы"}],"kz":{"text":"EXPO-2017 в Астане. Международная выставка, которую Казахстан провёл в 2017 году, объединяет все темы модуля: SMART-цели, график подготовки, риски, сценарий открытия, бюджет и анализ итогов.","link":""},"world":{"text":"Фестиваль Fyre Festival (2017, Багамы) стал мировым примером провала ивента из-за отсутствия плана, рисков и честной коммуникации с гостями.","link":""},"fact":"Слово «дедлайн» (deadline) в английском языке появилось в XIX веке и первоначально означало черту в лагере для военнопленных, за которую нельзя было заходить. Значение «крайний срок» закрепилось в XX веке в издательском деле.","cards":[{"n":"1","title":"Тест (10 вопросов, по 1 баллу)","lines":["1) Event — это: а) проект; б) мероприятие; в) прибыль.","2) SMART-цель — это: а) «Сделать крутой праздник»; б) «20 декабря принять 50 гостей за 90 минут»; в) «Заработать много».","3) Диаграмма Ганта показывает: а) задачи по дням; б) доходы; в) конфликты.","4) План Б включают: а) всегда; б) по заранее заданному сигналу; в) никогда.","5) Спор о том, кто какую часть делает, — конфликт: а) отношений; б) ценностей; в) задач.","6) Дедлайн — это: а) последний срок; б) цель; в) бюджет.","7) Прибыль = а) доходы + расходы; б) доходы − расходы; в) только доходы.","8) Прогон — это: а) реклама; б) репетиция ивента; в) подсчёт денег.","9) Критический риск: а) может сорвать ивент; б) почти не мешает; в) всегда полезен.","10) Анализ проекта проводят: а) до ивента; б) после ивента; в) не проводят."],"hand":null,"answers":[]},{"n":"2","title":"Практическое задание «Мини-проект ивента»","lines":["Ситуация: класс проводит турнир по настольным играм для 5 классов, 90 минут, 40 гостей.","Доходы: взносы команд 8 000 условных тенге, продажа чая 3 000.","Расходы: призы 5 000, чай и стаканы 1 500, печать 1 000.","Задание: 1) Запишите SMART-цель (2 балла). 2) Назовите 3 риска и план Б для главного (3 балла). 3) Распишите тайминг из 5 блоков на 90 минут (2 балла). 4) Посчитайте доходы, расходы и прибыль (3 балла)."],"hand":"Сдать: бланк работы.","answers":[]},{"n":"3","title":"Чек-лист самопроверки","lines":["Я ответил на все 10 вопросов.","Моя цель содержит дату и число.","У плана Б есть сигнал и ответственный.","Сумма минут = 90.","Я дважды проверил расчёт прибыли."],"hand":"Сдать: вместе с работой.","answers":[]},{"n":"4","title":"Ключ (для тренера)","lines":["Тест: 1б, 2б, 3а, 4б, 5в, 6а, 7б, 8б, 9а, 10б. Практика: доходы 11 000, расходы 7 500, прибыль 3 500 условных тенге."],"hand":null,"answers":[]}],"homework":"Записать 2 темы модуля, в которых чувствуешь себя уверенно, и 1 тему, которую хочешь повторить на следующем уроке.","support":"Схема пути ивента на доске как опора; для учеников с трудностями — практическое задание с шаблоном таблиц и увеличенное время на 3 минуты за счёт самопроверки.","advanced":"Дополнительное задание: найти позитивный риск для ивента из Карточки 2 и предложить, как его использовать, с расчётом в условных тенге (до 2 бонусных баллов, но не выше 10).","photo":{"src":"lessons/img/07_30.jpg","author":"Vitaly Gariev","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие 3 темы нашего модуля помогли бы организаторам избежать провала?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l30.pptx","name":"30. Итоговая работа за полугодие (Рефлексивное занятие) (7 кл).pptx","mb":1.3}},{"id":"07_31","g":7,"l":31,"topic":"Работа над ошибками и обратная связь по итоговой работе","module":"Event-менеджмент","format":"Итоговая работа","skills":["Лидерство","Критическое мышление"],"goal":"К концу урока ученик сможет найти в своей итоговой работе все ошибки, определить их тип, исправить их с объяснением и составить личный план из 2 шагов по слабой теме.","criteria":["Я нахожу все свои ошибки и определяю их тип: не знал термин, невнимательность, ошибка в расчёте.","Я исправляю каждую ошибку и объясняю правильный ответ своими словами.","Я составляю план из 2 шагов по теме, где ошибок больше всего."],"result":"Лист работы над ошибками: таблица «ошибка — тип — правильный ответ — почему» и личный план улучшения из 2 шагов с обратной связью тренера.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Ошибка (mistake)","real":"Неверный ответ или действие, из которого можно извлечь урок","shown":"Неверный ответ или действие, из которого можно извлечь урок","truth":true,"first":"О"},{"term":"Обратная связь (feedback)","real":"Комментарий о том, что получилось и что улучшить","shown":"В обратной связи сначала называем, что получилось","truth":false,"first":"О"},{"term":"Тип ошибки","real":"Причина ошибки: незнание, невнимательность, неверный расчёт","shown":"Причина ошибки: незнание, невнимательность, неверный расчёт","truth":true,"first":"Т"},{"term":"Работа над ошибками","real":"Исправление ошибок с объяснением","shown":"Комментарий о том, что получилось и что улучшить","truth":false,"first":"Р"},{"term":"Личный план улучшения","real":"Шаги, которые ученик сделает, чтобы закрыть пробел","shown":"Шаги, которые ученик сделает, чтобы закрыть пробел","truth":true,"first":"Л"},{"term":"Правило «сначала сильное»","real":"В обратной связи сначала называем, что получилось","shown":"Исправление ошибок с объяснением","truth":false,"first":"П"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Ошибка (mistake)","def":"Неверный ответ или действие, из которого можно извлечь урок"},{"term":"Обратная связь (feedback)","def":"Комментарий о том, что получилось и что улучшить"},{"term":"Тип ошибки","def":"Причина ошибки: незнание, невнимательность, неверный расчёт"},{"term":"Работа над ошибками","def":"Исправление ошибок с объяснением"},{"term":"Личный план улучшения","def":"Шаги, которые ученик сделает, чтобы закрыть пробел"},{"term":"Правило «сначала сильное»","def":"В обратной связи сначала называем, что получилось"}],"english":"mistake — ошибка; feedback — обратная связь","concepts":{"head":"Понятия","items":["Ошибка (mistake) — это информация о том, что нужно повторить.","Обратная связь (feedback) от тренера помогает понять, где пробел.","Ошибки бывают трёх типов: Т — не знал термин или правило; В — невнимательность (знал, но не заметил); Р — ошибка в расчёте."]},"steps":{"head":"Как работать, по шагам","items":["Прочитать комментарий тренера: что получилось","Выписать все ошибки в таблицу","Поставить каждой тип Т, В или Р","Найти правильный ответ в конспекте или у соседа-эксперта","Объяснить, почему он правильный","Посчитать, каких ошибок больше; ж) записать 2 шага улучшения"]},"scheme":"Таблица «Ошибка — Тип (Т/В/Р) — Правильно — Почему»; под ней «Мой план: шаг 1… шаг 2…» и три подсказки: Т → повторить конспект и карточки; В → чек-лист проверки; Р → решить 3 похожие задачи.","examples":[{"lab":"Казахстанский","text":"Ученик в Актау посчитал прибыль турнира так: 11 000 + 7 500 = 18 500. Тип Р (перепутал знак). Правильно: 11 000 − 7 500 = 3 500 условных тенге, потому что прибыль = доходы − расходы."},{"lab":"Мировой","text":"В авиации пилоты разбирают каждую ошибку на тренажёре, не для наказания, а чтобы она не повторилась в реальном полёте."}],"mistake":{"myth":"Ученики просто переписывают правильный ответ с доски","fix":"Требование — колонка «Почему» обязательна, без неё исправление не засчитывается."},"check":[{"q":"Какой тип ошибки исправляется чек-листом?","a":"В — невнимательность"},{"q":"Что делать, если много ошибок типа Т?","a":"Повторить термины, сделать карточки"},{"q":"Зачем объяснять правильный ответ?","a":"Чтобы понять, а не просто переписать"}],"kz":{"text":"Бокс и тренерский разбор в Казахстане. Казахстанский боксёр Геннадий Головкин и олимпийские чемпионы страны по боксу известны многолетней работой с тренерами, которые разбирают каждый бой и находят ошибки.","link":"чемпионы растут через анализ ошибок и обратную связь."},"world":{"text":"Мировая авиация стала одной из самых безопасных отраслей благодаря культуре разбора ошибок: инциденты изучают открыто, а выводы передают пилотам по всему миру.","link":""},"fact":"Томас Эдисон перепробовал тысячи материалов для нити лампы накаливания, прежде чем нашёл подходящий; его подход к неудачным опытам как к полезной информации стал знаменитым примером в истории изобретательства.","cards":[{"n":"1","title":"Лист работы над ошибками","lines":["Задание: заполните таблицу «№ задания — Моя ошибка — Тип (Т — не знал, В — невнимательность, Р — расчёт) — Правильно — Почему». Посчитайте, каких ошибок больше."],"hand":"Сдать: таблицу тренеру.","answers":[]},{"n":"2","title":"Мой план улучшения","lines":["Задание: допишите: «Больше всего у меня ошибок типа … Шаг 1: … до … Шаг 2: … до …» Подсказки: Т — повторить конспект, сделать 5 карточек «термин — определение»; В — использовать чек-лист проверки; Р — решить 3 похожие задачи."],"hand":"Сдать: план вместе с листом ошибок.","answers":[]},{"n":"3","title":"Контрольные вопросы","lines":["1) Доходы ивента 9 000, расходы 6 500 условных тенге. Прибыль?","2) Перепишите цель «Провести хороший концерт» в SMART-цель.","3) Чем риск отличается от проблемы?"],"hand":"Сдать: проверить по ключу на слайде.","answers":[["1","2 500."],["3","Риск ещё не случился."]]}],"homework":"Выполнить первый шаг личного плана улучшения (повторить термины, решить 3 задачи или составить чек-лист) и показать тренеру.","support":"Подсказки с номерами страниц конспекта к каждому вопросу теста; работа в паре с «экспертом»; разрешено исправлять ошибки устно с тренером.","advanced":"Для ученика без ошибок: составить 3 новых вопроса теста по самым трудным темам с ключом и стать «экспертом» для одноклассников.","photo":{"src":"lessons/img/07_31.jpg","author":"lilartsy","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему открыто разбирать ошибки полезнее, чем скрывать их?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l31.pptx","name":"31. Работа над ошибками и обратная связь по итоговой работе (7 кл).pptx","mb":1.4}},{"id":"07_32","g":7,"l":32,"topic":"Игра-повторение по темам полугодия","module":"Event-менеджмент","format":"Деловая игра","skills":["Лидерство","Критическое мышление","Командная работа"],"goal":"К концу урока ученик сможет в командной игре правильно применить не менее 5 понятий полугодия (SMART-цель, риск и план Б, дедлайн, тайминг, прибыль) и исправить хотя бы одну тему, в которой ошибался в итоговой работе.","criteria":["Я правильно применяю понятия полугодия в заданиях игры.","Я вместе с командой принимаю решение за отведённое время и выполняю свою роль.","Я называю, какую тему, где раньше ошибался, теперь понимаю."],"result":"Результат игры «Битва ивент-агентств»: таблица очков команды за 2 раунда и вывод команды «какие понятия помогли выиграть».","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Инструктаж","min":4},{"stage":"Раунд 1","min":10},{"stage":"Раунд 2","min":10},{"stage":"Разбор","min":8},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Повторение (review)","real":"Закрепление изученного через новые задания","shown":"Закрепление изученного через новые задания","truth":true,"first":"П"},{"term":"Игра (game)","real":"Задания с правилами, ролями и подсчётом очков","shown":"Доходы минус расходы","truth":false,"first":"И"},{"term":"SMART-цель","real":"Конкретная, измеримая, достижимая, важная цель со сроком","shown":"Конкретная, измеримая, достижимая, важная цель со сроком","truth":true,"first":"S"},{"term":"План Б","real":"Запасной вариант на случай риска","shown":"Задания с правилами, ролями и подсчётом очков","truth":false,"first":"П"},{"term":"Тайминг","real":"Расписание ивента по минутам","shown":"Расписание ивента по минутам","truth":true,"first":"Т"},{"term":"Прибыль","real":"Доходы минус расходы","shown":"Запасной вариант на случай риска","truth":false,"first":"П"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Повторение (review)","def":"Закрепление изученного через новые задания"},{"term":"Игра (game)","def":"Задания с правилами, ролями и подсчётом очков"},{"term":"SMART-цель","def":"Конкретная, измеримая, достижимая, важная цель со сроком"},{"term":"План Б","def":"Запасной вариант на случай риска"},{"term":"Тайминг","def":"Расписание ивента по минутам"},{"term":"Прибыль","def":"Доходы минус расходы"},{"term":"Ивент-агентство","def":"Компания, которая организует мероприятия для заказчиков"}],"english":"review — повторение; game — игра","concepts":{"head":"Понятия для повторения","items":["ивент, проект, менеджер, SMART-цель, диаграмма Ганта, риск (негативный, позитивный), план Б, конфликт задач/ценностей/отношений, дедлайн, сценарий и тайминг, доходы, расходы, прибыль, анализ проекта."]},"steps":{"head":"Как устроена игра, по шагам","items":["Класс делится на 4–5 «ивент-агентств» по 4–5 человек","Роли: директор (финальное решение), финансист (расчёты), риск-менеджер, хронометрист, спикер","Раунд 1 «Блиц-тендер»: 10 вопросов-карточек по терминам, у агентства 45 секунд на ответ, 1 очко за верный","Раунд 2 «Заказ клиента»: агентство получает заказ ивента и за 7 минут готовит SMART-цель, тайминг, 2 риска с планом Б и расчёт прибыли; в середине раунда тренер вводит событие рынка","Разбор решений"]},"scheme":"Табло очков «Агентство — Раунд 1 — Раунд 2 — Бонус — Итого» и рядом шкала оценки заказа: SMART-цель 2, тайминг 2, риски и план Б 3, расчёт 3.","examples":[{"lab":"Казахстанский","text":"«Акимат района заказывает праздник двора в Алматы на 60 минут для 80 жителей; бюджет 30 000 условных тенге, доход от продажи угощений ожидается 12 000»."},{"lab":"Мировой","text":"Агентства, организующие международные конференции, получают такие же заказы, только с тысячами гостей."}],"mistake":{"myth":"Команда спешит и не проверяет сумму минут или знак в расчёте","fix":"Хронометрист и финансист обязаны сказать «проверено» до сдачи; без этого — минус 1 очко."},"check":[],"kz":{"text":"Astana International Forum. Международный форум в Астане собирает гостей из многих стран; его организаторы работают с программой по минутам, безопасностью, бюджетом и рисками. В Раунде 2 используйте как образец: «Ваш заказ — мини-форум для школы».","link":"все понятия полугодия используются в реальном большом ивенте."},"world":{"text":"Международные ивент-агентства организуют конференции, фестивали и спортивные события по всему миру и сталкиваются с теми же задачами: цели, тайминг, риски, бюджет.","link":""},"fact":"Сборочный конвейер Генри Форда, запущенный в 1913 году, сократил время сборки автомобиля Model T примерно с 12 часов до полутора часов. Это пример того, как поиск узкого места в цепочке операций резко ускоряет работу.","cards":[{"n":"1","title":"Роли агентства","lines":["Директор — принимает финальное решение. Финансист — считает доходы, расходы, прибыль. Риск-менеджер — отвечает за риски и план Б. Хронометрист — следит за временем и суммой минут. Спикер — озвучивает ответы."],"hand":"Сдать: название агентства и роли на листке.","answers":[]},{"n":"2","title":"Блиц-тендер (вопросы для тренера)","lines":["1) Переделайте в SMART: «Провести праздник». 2) Доходы 15 000, расходы 9 500 — прибыль? (5 500.) 3) Что такое дедлайн? 4) Спор «что важнее — успеть или сделать качественно» — какой конфликт? (Ценностей.) 5) Приведите пример позитивного риска. 6) Что показывает диаграмма Ганта? (Задачи по дням.) 7) Блоки 10+15+20+10 мин — уложится ли ивент в 60 минут? (Да, 55 минут, 5 минут запаса.) 8) Когда включают план Б? (По сигналу.) 9) Назовите 3 вопроса анализа проекта. 10) Что такое прогон?"],"hand":null,"answers":[]},{"n":"3","title":"Заказ клиента","lines":["Заказ: праздник двора в Алматы, 60 минут, 80 жителей. Бюджет расходов — 30 000 условных тенге (сцена и звук 12 000, призы 8 000, угощения 6 000, украшения 4 000). Доход от продажи угощений — 12 000, спонсорский взнос — 25 000.","Задание за 7 минут: SMART-цель; тайминг из 5 блоков на 60 минут; 2 риска и план Б; расчёт прибыли","Событие (через 4 минуты): «Прогноз — дождь. Аренда навеса стоит 5 000 условных тенге». Пересчитайте прибыль (ответ: 2 000) и обновите план Б."],"hand":"Сдать: лист А3.","answers":[["","Доходы 37 000, расходы 30 000, прибыль 7 000"]]}],"practice":[{"type":"case","title":"Угадай проект: башня, которую хотели снести","minutes":6,"source":"Эйфелева башня, Париж, 1887–1889","hook":"Её построили на время для выставки, а художники требовали её снести.","story":["Башню построили за 2 года к Всемирной выставке 1889 года.","Многие известные художники и писатели писали протесты: «бесполезная и чудовищная башня».","Её разрешили оставить на 20 лет, а потом она пригодилась как радиобашня."],"question":"О каком проекте речь?","options":["Эйфелева башня","Биг-Бен","Статуя Свободы","Пизанская башня"],"answerIndex":0,"reveal":"Эйфелева башня построена точно в срок к выставке, а её «вторая жизнь» как радиобашни спасла её от сноса. Хороший проект иногда находит новое применение.","teams":"Команды: вспомните этапы проекта и назовите, на каком этапе Эйфель доказал, что башня нужна.","takeaway":"Проект оценивают и после завершения."},{"type":"case","title":"Угадай: метод с липкими листочками","minutes":6,"source":"Доска задач «канбан», производственная система Toyota","hook":"Японский метод с карточками «сделать — делаю — готово». Как он называется?","story":["На заводах Toyota придумали систему карточек, которая показывает, что делать дальше.","Сегодня этот метод используют для проектов: доска с колонками «сделать», «делаем», «готово».","Его название по-японски означает «вывеска» или «карточка»."],"question":"Как называется метод?","options":["Кайдзен","Канбан","Бусидо","Суши"],"answerIndex":1,"reveal":"Это канбан. Доска с карточками помогает команде видеть все задачи и не терять время. Кайдзен — тоже японское слово, оно означает постоянное улучшение.","teams":"Команды: нарисуйте канбан-доску для подготовки к следующему ивенту.","takeaway":"Видимые задачи — управляемые задачи."}],"homework":"Составить 3 вопроса для блиц-тендера по теме, в которой ошибался в итоговой работе, с ответами.","support":"Карточка-шпаргалка с 8 основными понятиями и формулой прибыли на столе каждого агентства; роль хронометриста или спикера для тех, кому трудно.","advanced":"Роль «аудитора»: проверить расчёт и тайминг другого агентства в Раунде 2 и найти ошибку за бонусное очко.","photo":{"src":"lessons/img/07_32.jpg","author":"National Cancer Institute","q":["Что вы видите на фото? Как это связано с нашей темой?","Какое понятие нашего модуля, по-вашему, самое важное для организатора международного события и почему?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g07-l32.pptx","name":"32. Игра-повторение по темам полугодия (7 кл).pptx","mb":1.5}}];
